(window.KOTOBA_HK=window.KOTOBA_HK||{})[27]={"n":27,"S":[{"id":"l27a","ti":[[["三びき","さんびき"],["の","の"],["子ぶた","こぶた"],["と","と"],["新しい","あたらしい"],["家","いえ"]]],"tt":{"az":"Üç balaca donuz və yeni ev","en":"The Three Little Pigs and Their New Houses","ru":"Три поросёнка и новые домики"},"P":[{"t":[[["むかしむかし","むかしむかし"],["、"],["森","もり"],["の","の"],["近く","ちかく"],["に","に"],["、"],["三びき","さんびき"],["の","の"],["子ぶた","こぶた"],["が","が"],["住んでいました","すんでいました","住む",31],["。"],["ある","ある","ある(連体詞)"],["春","はる"],["の","の"],["日","ひ"],["、"],["お母さん","おかあさん"],["は","は"],["「"],["もう","もう"],["大きく","おおきく","大きい"],["なりました","なりました","なる",2],["ね","ね"],["。"],["自分","じぶん"],["の","の"],["家","いえ"],["を","を"],["作りましょう","つくりましょう","作る",20],["」"],["と","と"],["言いました","いいました","言う",2],["。"],["三びき","さんびき"],["は","は"],["、"],["夏","なつ"],["まで","まで"],["に","に"],["家","いえ"],["を","を"],["作ろう","つくろう","作る",7],["と","と"],["思っていました","おもっていました","思う",15],["。"]]],"tr":{"az":"Biri var idi, biri yox idi, meşənin yaxınlığında üç balaca donuz yaşayırdı. Bir yaz günü anaları dedi: «Artıq böyümüsünüz. Gəlin öz evlərinizi tikək». Üçü də yaya qədər ev tikməyi düşünürdü.","en":"Once upon a time, three little pigs lived near a forest. One spring day, their mother said, “You're all grown up now. Let's build your own houses.” The three pigs were thinking of building their houses before summer.","ru":"Давным-давно возле леса жили три поросёнка. Однажды весной мама сказала: «Вы уже выросли. Давайте построим вам собственные домики». Все трое собирались построить дома до лета."}},{"t":[[["一ばん","いちばん"],["上","うえ"],["の","の"],["子ぶた","こぶた"],["は","は"],["、"],["わら","わら"],["の","の"],["家","いえ"],["を","を"],["作る","つくる","作る",5],["つもり","つもり"],["でした","でした","です",9],["。"],["「"],["早く","はやく","早い"],["作って","つくって","作る",3],["、"],["たくさん","たくさん"],["遊ぼう","あそぼう","遊ぶ",7],["」"],["と","と"],["考えました","かんがえました","考える",2],["。"],["二","に"],["ばん目","ばんめ"],["の","の"],["子ぶた","こぶた"],["は","は"],["、"],["木","き"],["の","の"],["家","いえ"],["を","を"],["作る","つくる","作る",5],["予定","よてい"],["でした","でした","です",9],["。"],["三","さん"],["ばん目","ばんめ"],["の","の"],["子ぶた","こぶた"],["は","は"],["、"],["強い","つよい"],["家","いえ"],["を","を"],["作ろう","つくろう","作る",7],["と","と"],["思っていました","おもっていました","思う",15],["。"]]],"tr":{"az":"Böyük donuz saman ev tikmək niyyətində idi. «Tez tikib çoxlu oynayım», deyə düşündü. Ortancıl donuz taxta ev tikməyi planlaşdırmışdı. Kiçik donuz isə möhkəm ev tikməyi düşünürdü.","en":"The oldest pig intended to build a straw house. He thought, “I'll finish quickly and play a lot.” The middle pig planned to build a wooden house. The youngest pig was thinking of building a strong house.","ru":"Старший поросёнок собирался построить дом из соломы. Он подумал: «Быстро построю и буду много играть». Средний поросёнок планировал построить деревянный дом. А младший собирался построить прочный дом."}},{"t":[[["上","うえ"],["の","の"],["二ひき","にひき"],["は","は"],["、"],["すぐ","すぐ"],["に","に"],["家","いえ"],["を","を"],["作りました","つくりました","作る",2],["。"],["でも","でも"],["、"],["三","さん"],["ばん目","ばんめ"],["は","は"],["、"],["まだ","まだ"],["家","いえ"],["を","を"],["作っていませんでした","つくっていませんでした","作る",28],["。"],["毎日","まいにち"],["、"],["石","いし"],["を","を"],["運んでいました","はこんでいました","運ぶ",31],["。"],["兄たち","あにたち"],["は","は"],["「"],["まだ","まだ"],["できない","できない","できる",19],["の","の"],["」"],["と","と"],["笑いました","わらいました","笑う",2],["が","が"],["、"],["三","さん"],["ばん目","ばんめ"],["は","は"],["あわてない","あわてない","あわてる",19],["つもり","つもり"],["でした","でした","です",9],["。"]]],"tr":{"az":"İki böyük donuz evlərini tez tikdi. Amma kiçik donuz hələ evini tikib qurtarmamışdı. O, hər gün daş daşıyırdı. Qardaşları «Hələ də hazır deyil?» deyə gülürdülər, amma kiçik donuz tələsməmək qərarında idi.","en":"The two older pigs built their houses quickly. But the youngest had not finished his house yet. Every day, he carried stones. His brothers laughed and asked, “Still not finished?” But the youngest had decided not to rush.","ru":"Два старших поросёнка быстро построили свои домики. Но младший ещё не закончил свой дом. Каждый день он носил камни. Братья смеялись: «До сих пор не готово?» Но младший решил не торопиться."}},{"t":[[["ある日","あるひ"],["、"],["大きな","おおきな"],["オオカミ","オオカミ"],["が","が"],["森","もり"],["から","から"],["来ました","きました","来る",2],["。"],["オオカミ","オオカミ"],["は","は"],["おなか","おなか"],["が","が"],["すいて","すいて","すく",3],["、"],["子ぶたたち","こぶたたち"],["の","の"],["食べ物","たべもの"],["を","を"],["ほしがりました","ほしがりました","ほす",2],["。"],["わら","わら"],["の","の"],["家","いえ"],["の","の"],["ドア","ドア"],["を","を"],["開けよう","あけよう","開ける",7],["と","と"],["しました","しました","する",2],["が","が"],["、"],["開きませんでした","ひらきませんでした","開く",4],["。"],["そこ","そこ"],["で","で"],["、"],["強い","つよい"],["風","かぜ"],["を","を"],["ふく","ふく","ふく",5],["こと","こと"],["に","に"],["しました","しました","する",2],["。"]]],"tr":{"az":"Bir gün meşədən böyük bir canavar gəldi. Canavar ac idi və donuzların yeməyini istəyirdi. Saman evin qapısını açmağa çalışdı, amma qapı açılmadı. Buna görə də güclü üfürmək qərarına gəldi.","en":"One day, a big wolf came out of the forest. The wolf was hungry and wanted the pigs' food. He tried to open the straw house's door, but it would not open. So he decided to blow hard.","ru":"Однажды из леса пришёл большой волк. Волк проголодался и захотел еду поросят. Он попытался открыть дверь соломенного домика, но она не открылась. Тогда он решил сильно подуть."}},{"t":[[["わら","わら"],["の","の"],["家","いえ"],["は","は"],["、"],["すぐ","すぐ"],["に","に"],["こわれました","こわれました","こわれる",2],["。"],["一ばん","いちばん"],["上","うえ"],["の","の"],["子ぶた","こぶた"],["は","は"],["、"],["木","き"],["の","の"],["家","いえ"],["へ","へ"],["走りました","はしりました","走る",2],["。"],["しかし","しかし"],["、"],["オオカミ","オオカミ"],["が","が"],["もう","もう"],["一度","いちど"],["ふく","ふく","ふく",5],["と","と"],["、"],["木","き"],["の","の"],["家","いえ"],["も","も"],["こわれました","こわれました","こわれる",2],["。"],["二ひき","にひき"],["は","は"],["、"],["三","さん"],["ばん目","ばんめ"],["の","の"],["家","いえ"],["へ","へ"],["にげる","にげる","にげる",5],["こと","こと"],["に","に"],["しました","しました","する",2],["。"]]],"tr":{"az":"Saman ev dərhal dağıldı. Böyük donuz taxta evə qaçdı. Amma canavar bir də üfürəndə taxta ev də dağıldı. İki qardaş kiçik donuzun evinə qaçmaq qərarına gəldi.","en":"The straw house fell apart immediately. The oldest pig ran to the wooden house. But when the wolf blew again, the wooden house fell apart too. The two pigs decided to escape to their youngest brother's house.","ru":"Соломенный домик сразу развалился. Старший поросёнок побежал в деревянный дом. Но когда волк подул ещё раз, деревянный дом тоже разрушился. Два брата решили убежать к младшему."}},{"t":[[["石","いし"],["の","の"],["家","いえ"],["は","は"],["、"],["もう","もう"],["できていました","できていました","できる",15],["。"],["オオカミ","オオカミ"],["は","は"],["家","いえ"],["を","を"],["こわそう","こわそう","こわす",7],["と","と"],["しました","しました","する",2],["が","が"],["、"],["できませんでした","できませんでした","できる",4],["。"],["オオカミ","オオカミ"],["は","は"],["つかれて","つかれて","つく",65],["、"],["泣きたがりました","なきたがりました","泣く",2],["。"],["三","さん"],["ばん目","ばんめ"],["の","の"],["子ぶた","こぶた"],["は","は"],["、"],["窓","まど"],["から","から"],["「"],["おなか","おなか"],["が","が"],["すいています","すいています","すく",24],["か","か"],["」"],["と","と"],["聞きました","ききました","聞く",2],["。"]]],"tr":{"az":"Daş ev artıq hazır idi. Canavar evi dağıtmağa çalışdı, amma bacarmadı. O, yoruldu və ağlamaq istədi. Kiçik donuz pəncərədən soruşdu: «Acsan?»","en":"The stone house was already finished. The wolf tried to knock it down, but he could not. He grew tired and looked ready to cry. The youngest pig asked through the window, “Are you hungry?”","ru":"Каменный дом уже был готов. Волк попытался разрушить его, но не смог. Он устал и чуть не заплакал. Младший поросёнок спросил из окна: «Ты голоден?»"}},{"t":[[["子ぶたたち","こぶたたち"],["は","は"],["、"],["オオカミ","オオカミ"],["に","に"],["温かい","あたたかい"],["スープ","スープ"],["を","を"],["あげる","あげる","あげる",5],["こと","こと"],["に","に"],["しました","しました","する",2],["。"],["オオカミ","オオカミ"],["は","は"],["びっくり","びっくり"],["しました","しました","する",2],["が","が"],["、"],["おいし","おいし","おいしい"],["そうに","そうに","そう",8],["食べました","たべました","食べる",2],["。"],["そして","そして"],["、"],["もう","もう"],["家","いえ"],["を","を"],["こわさない","こわさない","こわす",19],["こと","こと"],["に","に"],["しました","しました","する",2],["。"],["みんな","みんな"],["で","で"],["、"],["庭","にわ"],["に","に"],["花","はな"],["を","を"],["植える","うえる","植える",5],["予定","よてい"],["も","も"],["決めました","きめました","決める",2],["。"]]],"tr":{"az":"Donuzlar canavara isti şorba vermək qərarına gəldilər. Canavar təəccübləndi, amma şorbanı iştahla içdi. Sonra bir daha evləri dağıtmamağa qərar verdi. Hamısı birlikdə bağçada gül əkməyi də planlaşdırdı.","en":"The pigs decided to give the wolf some warm soup. He was surprised, but ate it happily. Then he decided never to destroy houses again. Together, they also made plans to plant flowers in the garden.","ru":"Поросята решили угостить волка тёплым супом. Волк удивился, но с удовольствием поел. Потом он решил больше никогда не разрушать дома. Все вместе они также запланировали посадить цветы в саду."}},{"t":[[["夏","なつ"],["に","に"],["なる","なる","なる",5],["と","と"],["、"],["三びき","さんびき"],["は","は"],["石","いし"],["の","の"],["家","いえ"],["で","で"],["楽しく","たのしく","楽しい"],["暮らしました","くらしました","暮らす",2],["。"],["オオカミ","オオカミ"],["も","も"],["毎週","まいしゅう"],["遊び","あそび","遊ぶ",10],["に","に"],["来る","くる","来る",5],["こと","こと"],["に","に"],["なりました","なりました","なる",2],["。"],["ある日","あるひ"],["、"],["オオカミ","オオカミ"],["は","は"],["「"],["今度","こんど"],["は","は"],["自分","じぶん"],["の","の"],["家","いえ"],["を","を"],["作ろう","つくろう","作る",7],["」"],["と","と"],["言いました","いいました","言う",2],["。"],["でも","でも"],["、"],["まだ","まだ"],["石","いし"],["を","を"],["一つ","ひとつ"],["も","も"],["運んでいませんでした","はこんでいませんでした","運ぶ",66],["。"]]],"tr":{"az":"Yay gələndə üç donuz daş evdə xoşbəxt yaşayırdı. Canavarın da hər həftə qonaq gəlməsi qərarlaşdırıldı. Bir gün canavar dedi: «Bu dəfə özümə ev tikim». Amma o, hələ bir dənə də daş daşımamışdı.","en":"When summer came, the three pigs lived happily in the stone house. It was also arranged that the wolf would visit every week. One day, the wolf said, “This time, I'll build my own house.” But he had not carried even one stone yet.","ru":"Когда наступило лето, три поросёнка счастливо жили в каменном доме. Волк тоже стал приходить к ним каждую неделю. Однажды он сказал: «Теперь построю собственный дом». Но пока он не принёс ни одного камня."}}]},{"id":"l27b","ti":[[["星空","ほしぞら"],["キャンプ","キャンプ"],["の","の"],["小さな","ちいさな"],["ロケット","ロケット"]]],"tt":{"az":"Ulduz düşərgəsinin balaca raketi","en":"The Little Rocket at Star Camp","ru":"Маленькая ракета в звёздном лагере"},"P":[{"t":[[["ある","ある","ある(連体詞)"],["夏","なつ"],["、"],["小さな","ちいさな"],["町","まち"],["に","に"],["宇宙","うちゅう"],["キャンプ","キャンプ"],["が","が"],["できました","できました","できる",2],["。"],["空","そら"],["を","を"],["見る","みる","見る",5],["の","の"],["が","が"],["好きな","すきな","好き",1],["女の子","おんなのこ"],["、"],["ミオ","ミオ"],["は","は"],["、"],["友だち","ともだち"],["の","の"],["ソラ","ソラ"],["と","と"],["参加","さんか"],["する","する","する",5],["予定","よてい"],["でした","でした","です",9],["。"],["二人","ふたり"],["は","は"],["小さな","ちいさな"],["ロケット","ロケット"],["を","を"],["作ろう","つくろう","作る",7],["と","と"],["思っていました","おもっていました","思う",15],["。"],["ミオ","ミオ"],["は","は"],["「"],["いつ","いつ"],["か","か"],["宇宙","うちゅう"],["へ","へ"],["行こう","いこう","行く",7],["」"],["と","と"],["、"],["毎晩","まいばん"],["星","ほし"],["を","を"],["見ていました","みていました","見る",15],["。"]]],"tr":{"az":"Bir yay balaca şəhərdə kosmos düşərgəsi açıldı. Göyə baxmağı sevən Mio adlı qız dostu Sora ilə düşərgəyə qatılmağı planlaşdırmışdı. Onlar kiçik bir raket hazırlamağı düşünürdülər. Mio hər gecə ulduzlara baxıb «Bir gün kosmosa gedək», deyirdi.","en":"One summer, a space camp opened in a small town. A girl named Mio, who loved looking at the sky, planned to attend with her friend Sora. They were thinking of building a small rocket. Every night, Mio looked at the stars and said, “Someday, let's go into space.”","ru":"Однажды летом в маленьком городке открылся космический лагерь. Девочка Мио, которая любила смотреть на небо, собиралась поехать туда со своим другом Сорой. Они задумали построить маленькую ракету. Каждый вечер Мио смотрела на звёзды и говорила: «Когда-нибудь полетим в космос»."}},{"t":[[["キャンプ","キャンプ"],["に","に"],["は","は"],["、"],["ロケット","ロケット"],["の","の"],["材料","ざいりょう"],["が","が"],["たくさん","たくさん"],["ありました","ありました","ある",2],["。"],["ソラ","ソラ"],["は","は"],["大きい","おおきい"],["ロケット","ロケット"],["を","を"],["作りたがりました","つくりたがりました","作る",2],["。"],["でも","でも"],["、"],["ミオ","ミオ"],["は","は"],["小さい","ちいさい"],["ロケット","ロケット"],["に","に"],["する","する","する",5],["つもり","つもり"],["でした","でした","です",9],["。"],["「"],["軽い","かるい"],["ほう","ほう"],["が","が"],["いい","いい"],["よ","よ"],["」"],["と","と"],["言って","いって","言う",3],["、"],["二人","ふたり"],["は","は"],["紙","かみ"],["と","と"],["木","き"],["を","を"],["使う","つかう","使う",5],["こと","こと"],["に","に"],["しました","しました","する",2],["。"]]],"tr":{"az":"Düşərgədə raket hazırlamaq üçün çoxlu material var idi. Sora böyük raket düzəltmək istəyirdi. Amma Mio kiçik raket düzəltmək niyyətində idi. «Yüngül olsa, daha yaxşıdır», dedi və ikisi kağızla taxtadan istifadə etməyə qərar verdi.","en":"There were plenty of rocket-building materials at the camp. Sora wanted to make a big rocket. But Mio intended to make a small one. “It's better if it's light,” she said, and they decided to use paper and wood.","ru":"В лагере было много материалов для ракет. Сора хотел построить большую ракету. Но Мио собиралась сделать маленькую. «Лучше, если она будет лёгкой», сказала она, и они решили использовать бумагу и дерево."}},{"t":[[["次","つぎ"],["の","の"],["日","ひ"],["、"],["みんな","みんな"],["は","は"],["ロケット","ロケット"],["を","を"],["作り","つくり","作る",10],["始めました","はじめました","始める",2],["。"],["ミオたち","ミオたち"],["は","は"],["、"],["まだ","まだ"],["エンジン","エンジン"],["を","を"],["つけていませんでした","つけていませんでした","つける",28],["。"],["先生","せんせい"],["は","は"],["「"],["明日","あした"],["の","の"],["朝","あさ"],["、"],["飛ばす","とばす","飛ばす",5],["予定","よてい"],["です","です"],["」"],["と","と"],["言いました","いいました","言う",2],["。"],["二人","ふたり"],["は","は"],["夜","よる"],["まで","まで"],["に","に"],["全部","ぜんぶ"],["作ろう","つくろう","作る",7],["と","と"],["しました","しました","する",2],["が","が"],["、"],["時間","じかん"],["が","が"],["足りませんでした","たりませんでした","足りる",4],["。"]]],"tr":{"az":"Ertəsi gün hamı raket hazırlamağa başladı. Mio ilə Sora hələ mühərriki quraşdırmamışdı. Müəllim dedi: «Raketləri sabah səhər uçurmağı planlaşdırırıq». Onlar axşama qədər hər şeyi bitirməyə çalışdılar, amma vaxt çatmadı.","en":"The next day, everyone began building rockets. Mio and Sora had not attached the engine yet. The teacher said, “We're planning to launch them tomorrow morning.” The two tried to finish everything by evening, but there was not enough time.","ru":"На следующий день все начали строить ракеты. Мио и Сора ещё не установили двигатель. Учитель сказал: «Завтра утром мы планируем запуск». Друзья попытались закончить всё к вечеру, но времени не хватило."}},{"t":[[["ソラ","ソラ"],["は","は"],["心配","しんぱい"],["して","して","する",3],["、"],["帰りたがりました","かえりたがりました","帰る",2],["。"],["ミオ","ミオ"],["も","も"],["少し","すこし"],["悲しく","かなしく","悲しい"],["なりました","なりました","なる",2],["。"],["でも","でも"],["、"],["二人","ふたり"],["は","は"],["あきらめない","あきらめない","あきらめる",19],["こと","こと"],["に","に"],["しました","しました","する",2],["。"],["先生","せんせい"],["に","に"],["手伝ってもらって","てつだってもらって","手伝う",67],["、"],["小さな","ちいさな"],["ロケット","ロケット"],["を","を"],["やっと","やっと"],["完成","かんせい"],["させました","させました","する",16],["。"]]],"tr":{"az":"Sora narahat oldu və evə qayıtmaq istədi. Mio da bir az kədərləndi. Amma onlar təslim olmamağa qərar verdilər. Müəllimin köməyi ilə nəhayət kiçik raketi tamamladılar.","en":"Sora became worried and wanted to go home. Mio felt a little sad too. But they decided not to give up. With the teacher's help, they finally completed their little rocket.","ru":"Сора заволновался и захотел домой. Мио тоже немного загрустила. Но они решили не сдаваться. С помощью учителя друзья наконец закончили маленькую ракету."}},{"t":[[["朝","あさ"],["に","に"],["なる","なる","なる",5],["と","と"],["、"],["大きな","おおきな"],["広場","ひろば"],["に","に"],["みんな","みんな"],["が","が"],["集まりました","あつまりました","集まる",2],["。"],["ミオたち","ミオたち"],["は","は"],["、"],["ロケット","ロケット"],["を","を"],["空","そら"],["へ","へ"],["飛ばそう","とばそう","飛ばす",7],["と","と"],["しました","しました","する",2],["。"],["しかし","しかし"],["、"],["ボタン","ボタン"],["を","を"],["押しても","おしても","押す",34],["、"],["ロケット","ロケット"],["は","は"],["動きませんでした","うごきませんでした","動く",4],["。"],["ほか","ほか"],["の","の"],["子どもたち","こどもたち"],["は","は"],["、"],["もう","もう"],["自分","じぶん"],["の","の"],["ロケット","ロケット"],["を","を"],["飛ばしていました","とばしていました","飛ばす",15],["。"]]],"tr":{"az":"Səhər hamı böyük meydana toplandı. Mio ilə Sora raketi göyə buraxmağa çalışdılar. Ancaq düyməyə bassalar da, raket tərpənmədi. Başqa uşaqlar isə artıq öz raketlərini uçurmuşdular.","en":"In the morning, everyone gathered in a large field. Mio and Sora tried to launch their rocket into the sky. But even when they pressed the button, the rocket did not move. The other children had already launched theirs.","ru":"Утром все собрались на большой площадке. Мио и Сора попытались запустить ракету в небо. Но даже после нажатия кнопки ракета не двигалась. Остальные дети уже запустили свои ракеты."}},{"t":[[["ミオ","ミオ"],["は","は"],["、"],["もう","もう"],["一度","いちど"],["調べる","しらべる","調べる",5],["こと","こと"],["に","に"],["しました","しました","する",2],["。"],["する","する","する",5],["と","と"],["、"],["小さな","ちいさな"],["線","せん"],["が","が"],["外れていました","はずれていました","外れる",15],["。"],["ソラ","ソラ"],["は","は"],["すぐ","すぐ"],["に","に"],["直して","なおして","直す",3],["、"],["「"],["もう","もう"],["一回","いっかい"],["やろう","やろう","やる",7],["」"],["と","と"],["言いました","いいました","言う",2],["。"],["今度","こんど"],["は","は"],["ロケット","ロケット"],["が","が"],["高く","たかく","高い"],["飛んで","とんで","飛ぶ",13],["、"],["青い","あおい"],["空","そら"],["の","の"],["中","なか"],["で","で"],["光りました","ひかりました","光る",2],["。"]]],"tr":{"az":"Mio hər şeyi yenidən yoxlamağa qərar verdi. Bu zaman kiçik bir naqilin çıxdığını gördü. Sora onu dərhal düzəldib «Bir də cəhd edək», dedi. Bu dəfə raket yüksəyə qalxdı və mavi səmada parıldadı.","en":"Mio decided to check everything again. Then she found a small disconnected wire. Sora fixed it immediately and said, “Let's try once more.” This time, the rocket flew high and shone against the blue sky.","ru":"Мио решила всё проверить ещё раз. Тогда она заметила, что маленький провод отсоединился. Сора быстро поправил его и сказал: «Попробуем ещё раз». На этот раз ракета взлетела высоко и засверкала в голубом небе."}},{"t":[[["ところ","ところ"],["が","が"],["、"],["ロケット","ロケット"],["は","は"],["急","きゅう"],["に","に","だ"],["森","もり"],["の","の"],["ほう","ほう"],["へ","へ"],["飛んでいきました","とんでいきました","飛ぶ",68],["。"],["二人","ふたり"],["は","は"],["急いで","いそいで","急ぐ",13],["追いかけました","おいかけました","追いかける",2],["。"],["森","もり"],["の","の"],["中","なか"],["に","に"],["は","は"],["、"],["ロケット","ロケット"],["の","の"],["そば","そば"],["で","で"],["小さな","ちいさな"],["犬","いぬ"],["が","が"],["しっぽ","しっぽ"],["を","を"],["振っていました","ふっていました","振る",15],["。"],["犬","いぬ"],["は","は"],["ロケット","ロケット"],["を","を"],["おもちゃ","おもちゃ"],["だ","だ","です"],["と","と"],["思って","おもって","思う",3],["、"],["持って","もって","持つ",3],["帰りたがりました","かえりたがりました","帰る",2],["。"]]],"tr":{"az":"Ancaq raket qəfildən meşəyə tərəf uçdu. İkisi də tələsik arxasınca qaçdı. Meşədə raketin yanında quyruğunu bulayan balaca bir it var idi. İt raketi oyuncaq sanmışdı və onu evə aparmaq istəyirdi.","en":"But suddenly, the rocket flew toward the forest. The two hurried after it. In the forest, a small dog was wagging its tail beside the rocket. The dog thought it was a toy and wanted to take it home.","ru":"Но вдруг ракета полетела в сторону леса. Друзья поспешили за ней. В лесу возле ракеты маленькая собака виляла хвостом. Она приняла ракету за игрушку и хотела унести её домой."}},{"t":[[["犬","いぬ"],["に","に"],["は","は"],["首輪","くびわ"],["が","が"],["ありませんでした","ありませんでした","ある",4],["。"],["二人","ふたり"],["は","は"],["犬","いぬ"],["を","を"],["キャンプ","キャンプ"],["へ","へ"],["連れて","つれて","連れる",3],["帰る","かえる","帰る",5],["こと","こと"],["に","に"],["しました","しました","する",2],["。"],["先生","せんせい"],["と","と"],["相談","そうだん"],["して","して","する",3],["、"],["飼い主","かいぬし"],["を","を"],["探す","さがす","探す",5],["こと","こと"],["に","に"],["なりました","なりました","なる",2],["。"],["ミオ","ミオ"],["は","は"],["「"],["来年","らいねん"],["は","は"],["もっと","もっと"],["遠く","とおく"],["へ","へ"],["飛ばそう","とばそう","飛ばす",7],["。"],["でも","でも"],["、"],["犬","いぬ"],["は","は"],["飛ばさない","とばさない","飛ばす",19],["つもり","つもり"],["です","です"],["」"],["と","と"],["笑いました","わらいました","笑う",2],["。"]]],"tr":{"az":"İtin boynunda xaltası yox idi. İkisi iti düşərgəyə aparmağa qərar verdi. Müəllimlə məsləhətləşdikdən sonra onun sahibini axtarmaq qərara alındı. Mio gülərək dedi: «Gələn il raketi daha uzağa uçuraq. Amma iti uçurmaq fikrim yoxdur!»","en":"The dog had no collar. The two decided to take it back to camp. After talking with their teacher, they agreed to look for its owner. Mio laughed and said, “Next year, let's fly even farther. But I'm not planning to launch the dog!”","ru":"На собаке не было ошейника. Друзья решили отвести её в лагерь. Посоветовавшись с учителем, они договорились найти её хозяина. Мио засмеялась: «В следующем году запустим ракету ещё дальше. Но собаку запускать я не собираюсь!»"}}]},{"id":"l27c","ti":[[["夏休み","なつやすみ"],["の","の"],["ひみつ","ひみつ"],["の","の"],["予定","よてい"]]],"tt":{"az":"Yay tətilinin gizli planı","en":"The Secret Summer Vacation Plan","ru":"Тайный план на летние каникулы"},"P":[{"t":[[["小さな","ちいさな"],["町","まち"],["に","に"],["、"],["ユキ","ユキ"],["と","と"],["いう","いう","いう",5],["女の子","おんなのこ"],["が","が"],["住んでいました","すんでいました","住む",31],["。"],["夏休み","なつやすみ"],["に","に"],["は","は"],["、"],["海","うみ"],["へ","へ"],["行こう","いこう","行く",7],["と","と"],["思っていました","おもっていました","思う",15],["。"],["お父さん","おとうさん"],["と","と"],["お母さん","おかあさん"],["も","も"],["、"],["一緒","いっしょ"],["に","に"],["行く","いく","行く",5],["予定","よてい"],["でした","でした","です",9],["。"],["ユキ","ユキ"],["は","は"],["新しい","あたらしい"],["水着","みずぎ"],["を","を"],["買いました","かいました","買う",2],["が","が"],["、"],["まだ","まだ"],["かばん","かばん"],["に","に"],["入れていませんでした","いれていませんでした","入れる",28],["。"]]],"tr":{"az":"Balaca bir şəhərdə Yuki adlı qız yaşayırdı. O, yay tətilində dənizə getməyi düşünürdü. Atası ilə anası da onunla getməyi planlaşdırmışdı. Yuki yeni çimərlik geyimi almışdı, amma hələ çantasına qoymamışdı.","en":"A girl named Yuki lived in a small town. She was thinking of going to the sea during summer vacation. Her mother and father planned to go with her. Yuki had bought a new swimsuit, but had not packed it yet.","ru":"В маленьком городке жила девочка по имени Юки. На летних каникулах она собиралась поехать к морю. Мама и папа тоже планировали поехать с ней. Юки купила новый купальник, но ещё не положила его в сумку."}},{"t":[[["ところ","ところ"],["が","が"],["、"],["旅行","りょこう"],["の","の"],["三日","みっか"],["前","まえ"],["、"],["お父さん","おとうさん"],["に","に"],["大切な","たいせつな","大切",1],["仕事","しごと"],["が","が"],["できました","できました","できる",2],["。"],["海","うみ"],["へ","へ"],["行く","いく","行く",5],["予定","よてい"],["は","は"],["、"],["なくなってしまいました","なくなってしまいました","なくなる",14],["。"],["ユキ","ユキ"],["は","は"],["泣きたがりました","なきたがりました","泣く",2],["が","が"],["、"],["泣かない","なかない","泣く",19],["つもり","つもり"],["でした","でした","です",9],["。"],["「"],["じゃあ","じゃあ"],["、"],["家","いえ"],["で","で"],["楽しく","たのしく","楽しい"],["遊ぼう","あそぼう","遊ぶ",7],["」"],["と","と"],["考えました","かんがえました","考える",2],["。"]]],"tr":{"az":"Amma səfərə üç gün qalmış atasının vacib işi çıxdı. Dənizə getmək planı ləğv olundu. Yukinin ağlamağı gəlirdi, amma ağlamamaq qərarında idi. «Onda evdə əyləncəli vaxt keçirək», deyə düşündü.","en":"But three days before the trip, her father had an important job to do. Their plan to go to the sea was canceled. Yuki felt like crying, but she intended not to cry. “Then let's have fun at home,” she thought.","ru":"Но за три дня до поездки у папы появилась важная работа. Поездку к морю пришлось отменить. Юки хотелось плакать, но она решила не плакать. «Тогда давайте весело проведём время дома», подумала она."}},{"t":[[["次","つぎ"],["の","の"],["朝","あさ"],["、"],["ユキ","ユキ"],["は","は"],["夏休み","なつやすみ"],["の","の"],["計画","けいかく"],["を","を"],["作る","つくる","作る",5],["こと","こと"],["に","に"],["しました","しました","する",2],["。"],["まず","まず"],["、"],["庭","にわ"],["に","に"],["小さな","ちいさな"],["プール","プール"],["を","を"],["出そう","だそう","出す",7],["と","と"],["しました","しました","する",2],["。"],["でも","でも"],["、"],["プール","プール"],["に","に"],["は","は"],["穴","あな"],["が","が"],["ありました","ありました","ある",2],["。"],["水","みず"],["を","を"],["入れても","いれても","入れる",34],["、"],["すぐ","すぐ"],["に","に"],["なくなりました","なくなりました","なくなる",2],["。"]]],"tr":{"az":"Ertəsi səhər Yuki yay tətili üçün plan hazırlamağa qərar verdi. Əvvəlcə həyətə kiçik hovuz qoymağa çalışdı. Amma hovuz deşik idi. İçinə su doldursa da, su tez boşalırdı.","en":"The next morning, Yuki decided to make a summer vacation plan. First, she tried to set up a small pool in the garden. But the pool had a hole. Even when she filled it with water, the water quickly disappeared.","ru":"На следующее утро Юки решила составить план летних каникул. Сначала она попыталась поставить маленький бассейн во дворе. Но в бассейне была дырка. Даже когда она наливала воду, та быстро вытекала."}},{"t":[[["ユキ","ユキ"],["は","は"],["プール","プール"],["を","を"],["使わない","つかわない","使う",19],["こと","こと"],["に","に"],["しました","しました","する",2],["。"],["かわり","かわり"],["に","に"],["、"],["青い","あおい"],["紙","かみ"],["で","で"],["大きな","おおきな"],["海","うみ"],["を","を"],["作ろう","つくろう","作る",7],["と","と"],["思いました","おもいました","思う",2],["。"],["弟","おとうと"],["の","の"],["タロウ","タロウ"],["も","も"],["手伝いたがりました","てつだいたがりました","手伝う",2],["。"],["二人","ふたり"],["は","は"],["紙","かみ"],["を","を"],["床","ゆか"],["に","に"],["並べて","ならべて","並べる",3],["、"],["魚","さかな"],["や","や"],["船","ふね"],["の","の"],["絵","え"],["を","を"],["かきました","かきました","かく",2],["。"]]],"tr":{"az":"Yuki hovuzdan istifadə etməməyə qərar verdi. Əvəzində mavi kağızdan böyük dəniz düzəltməyi düşündü. Kiçik qardaşı Taro da kömək etmək istəyirdi. İkisi kağızları döşəməyə düzdü, balıq və gəmi şəkilləri çəkdi.","en":"Yuki decided not to use the pool. Instead, she thought of making a big sea out of blue paper. Her little brother Taro wanted to help too. They spread the paper across the floor and drew fish and boats.","ru":"Юки решила не пользоваться бассейном. Вместо этого она задумала сделать большое море из синей бумаги. Её младший брат Таро тоже захотел помочь. Они разложили бумагу на полу и нарисовали рыб и кораблики."}},{"t":[[["午後","ごご"],["に","に"],["は","は"],["、"],["お母さん","おかあさん"],["と","と"],["おにぎり","おにぎり"],["を","を"],["作る","つくる","作る",5],["予定","よてい"],["でした","でした","です",9],["。"],["タロウ","タロウ"],["は","は"],["大きい","おおきい"],["おにぎり","おにぎり"],["を","を"],["食べたがりました","たべたがりました","食べる",2],["。"],["でも","でも"],["、"],["ごはん","ごはん"],["が","が"],["少し","すこし"],["しか","しか"],["ありませんでした","ありませんでした","ある",4],["。"],["そこ","そこ"],["で","で"],["、"],["二人","ふたり"],["は","は"],["小さい","ちいさい"],["おにぎり","おにぎり"],["を","を"],["たくさん","たくさん"],["作る","つくる","作る",5],["こと","こと"],["に","に"],["しました","しました","する",2],["。"]]],"tr":{"az":"Günortadan sonra anaları ilə onigiri hazırlamağı planlaşdırmışdılar. Taro böyük onigiri yemək istəyirdi. Amma düyü çox az idi. Buna görə onlar çoxlu balaca onigiri hazırlamağa qərar verdilər.","en":"In the afternoon, they planned to make rice balls with their mother. Taro wanted to eat a big rice ball. But there was only a little rice. So they decided to make many small rice balls.","ru":"После обеда они собирались приготовить онигири вместе с мамой. Таро хотел съесть большой рисовый шарик. Но риса оставалось совсем немного. Поэтому они решили сделать много маленьких онигири."}},{"t":[[["夕方","ゆうがた"],["、"],["お父さん","おとうさん"],["が","が"],["早く","はやく","早い"],["帰ってきました","かえってきました","帰る",23],["。"],["部屋","へや"],["の","の"],["中","なか"],["の","の"],["青い","あおい"],["海","うみ"],["を","を"],["見て","みて","見る",3],["、"],["とても","とても"],["びっくり","びっくり"],["しました","しました","する",2],["。"],["ユキ","ユキ"],["は","は"],["「"],["明日","あした"],["は","は"],["ここ","ここ"],["で","で"],["海","うみ"],["の","の"],["お祭り","おまつり"],["を","を"],["しよう","しよう","する",7],["」"],["と","と"],["言いました","いいました","言う",2],["。"],["お父さん","おとうさん"],["も","も"],["、"],["休み","やすみ"],["の","の"],["日","ひ"],["は","は"],["仕事","しごと"],["を","を"],["しない","しない","する",19],["こと","こと"],["に","に"],["しました","しました","する",2],["。"]]],"tr":{"az":"Axşamüstü ataları evə tez qayıtdı. Otaqdakı mavi dənizi görəndə çox təəccübləndi. Yuki dedi: «Sabah burada dəniz festivalı keçirək». Atası da istirahət günündə işləməməyə qərar verdi.","en":"That evening, their father came home early. He was very surprised to see the blue sea inside the room. Yuki said, “Tomorrow, let's have a seaside festival here.” Their father also decided not to work on his day off.","ru":"Вечером папа вернулся домой рано. Увидев синее море посреди комнаты, он очень удивился. Юки сказала: «Давайте завтра устроим здесь морской праздник». Папа тоже решил не работать в свой выходной."}},{"t":[[["次","つぎ"],["の","の"],["日","ひ"],["、"],["家族","かぞく"],["みんな","みんな"],["で","で"],["海","うみ"],["の","の"],["お祭り","おまつり"],["を","を"],["する","する","する",5],["こと","こと"],["に","に"],["なりました","なりました","なる",2],["。"],["お母さん","おかあさん"],["は","は"],["音楽","おんがく"],["を","を"],["かけ","かけ","かける",10],["、"],["お父さん","おとうさん"],["は","は"],["魚","さかな"],["の","の"],["帽子","ぼうし"],["を","を"],["かぶりました","かぶりました","かぶる",2],["。"],["タロウ","タロウ"],["は","は"],["紙","かみ"],["の","の"],["船","ふね"],["に","に"],["乗ろう","のろう","乗る",7],["と","と"],["しました","しました","する",2],["が","が"],["、"],["船","ふね"],["が","が"],["小さ","ちいさ","小さい"],["すぎました","すぎました","すぎる",2],["。"],["みんな","みんな"],["は","は"],["笑って","わらって","笑う",3],["、"],["おにぎり","おにぎり"],["を","を"],["食べました","たべました","食べる",2],["。"]]],"tr":{"az":"Ertəsi gün bütün ailənin evdə dəniz festivalı keçirməsi qərara alındı. Ana musiqi qoşdu, ata isə balıq formasında papaq taxdı. Taro kağız qayığa minməyə çalışdı, amma qayıq çox kiçik idi. Hamı güldü və onigiri yedi.","en":"The next day, the whole family held their seaside festival. Their mother played music, and their father wore a fish-shaped hat. Taro tried to get into a paper boat, but it was much too small. Everyone laughed and ate rice balls.","ru":"На следующий день вся семья устроила морской праздник дома. Мама включила музыку, а папа надел шапку в форме рыбы. Таро попытался сесть в бумажную лодку, но она оказалась слишком маленькой. Все смеялись и ели онигири."}},{"t":[[["夜","よる"],["、"],["お父さん","おとうさん"],["は","は"],["「"],["来年","らいねん"],["こそ","こそ"],["本当","ほんとう"],["の","の"],["海","うみ"],["へ","へ"],["行こう","いこう","行く",7],["」"],["と","と"],["言いました","いいました","言う",2],["。"],["ユキ","ユキ"],["は","は"],["うれし","うれし","うれしい"],["そうに","そうに","そう",8],["笑いました","わらいました","笑う",2],["。"],["でも","でも"],["、"],["来年","らいねん"],["の","の"],["予定","よてい"],["は","は"],["まだ","まだ"],["決めていませんでした","きめていませんでした","決める",28],["。"],["タロウ","タロウ"],["だけ","だけ"],["は","は"],["、"],["来年","らいねん"],["も","も"],["家","いえ"],["の","の"],["海","うみ"],["で","で"],["遊ぶ","あそぶ","遊ぶ",5],["つもり","つもり"],["でした","でした","です",9],["。"],["なぜ","なぜ"],["なら","なら","だ"],["、"],["紙","かみ"],["の","の"],["魚","さかな"],["を","を"],["百ぴき","ひゃくぴき"],["も","も"],["作ってしまった","つくってしまった","作る",69],["から","から"],["です","です"],["。"]]],"tr":{"az":"Axşam ataları dedi: «Gələn il mütləq əsl dənizə gedək». Yuki sevinclə gülümsədi. Amma gələn ilin planını hələ müəyyən etməmişdilər. Təkcə Taro gələn il də evdəki dənizdə oynamaq niyyətində idi. Çünki o, artıq yüz dənə kağız balıq düzəltmişdi.","en":"That night, their father said, “Next year, let's definitely go to the real sea.” Yuki smiled happily. But they had not decided on next year's plans yet. Taro alone intended to play in their homemade sea again next year. After all, he had already made a hundred paper fish!","ru":"Вечером папа сказал: «В следующем году обязательно поедем к настоящему морю». Юки радостно улыбнулась. Но планы на следующий год они ещё не определили. Только Таро собирался и в следующем году играть в домашнем море. Ведь он уже успел сделать целых сто бумажных рыбок!"}}]}],"G":{"あきらめる":{"b":"諦める (あきらめる)","p":"v","m":{"az":"əl çəkmək; təslim olmaq","en":"to give up; to abandon","ru":"сдаваться; отказываться"},"n":{"az":"一段 feilidir; あきらめませんでした əl çəkmədi deməkdir.","en":"An ichidan verb; あきらめませんでした means did not give up.","ru":"Глагол II группы; あきらめませんでした означает не сдался."}},"あげる":{"b":"あげる","p":"v","m":{"az":"vermək, hədiyyə etmək","en":"give","ru":"давать, дарить"},"n":{"az":"Alan şəxs に, verilən şey を ilə işlənir: 友達に本をあげる; danışana verilən şey üçün adətən くれる işlənir.","en":"The recipient takes に and the gift を, as in 友達に本をあげる; giving to the speaker is usually expressed with くれる.","ru":"Получатель обозначается с に, подарок с を: 友達に本をあげる; когда дают говорящему, обычно используется くれる."}},"ある":{"b":"ある","p":"v","m":{"az":"olmaq, var olmaq (cansız şeylər)","en":"to be, to exist (things)","ru":"быть, иметься (о предметах)"},"n":{"az":"Cansız şeylər üçün: 電池がありました = batareya var idi. Canlılar üçün いる. 書いてありました = yazılmışdı (yazılı vəziyyətdə idi).","en":"For non-living things: 電池がありました = there was a battery. For living things use いる. 書いてありました = was written (and stayed so).","ru":"Для неодушевлённых: 電池がありました = была батарейка. Для живых – いる. 書いてありました = было написано."}},"ある(連体詞)":{"b":"ある","p":"dm","m":{"az":"bir, hansısa (bir)","en":"a certain, one","ru":"некий, один"},"n":{"az":"ある朝 = bir səhər; ある日 = bir gün. İsimdən əvvəl gələndə 'var olmaq' feili deyil.","en":"ある朝 = one morning. Before a noun it is not the verb 'to exist'.","ru":"ある朝 = однажды утром. Перед существительным это не глагол 'быть'."}},"ある日":{"b":"ある日 (あるひ)","p":"ex","m":{"az":"bir gün","en":"one day","ru":"однажды"}},"あわてる":{"b":"慌てる (あわてる)","p":"v","m":{"az":"tələsib çaşmaq; özünü itirmək","en":"to panic; to act in a hurry","ru":"паниковать; суетиться"},"n":{"az":"慌てない inkar formasıdır və təlaşa düşməmək deməkdir.","en":"慌てない is the negative form, meaning not to panic.","ru":"慌てない является отрицательной формой и означает не паниковать."}},"いい":{"b":"いい・良い (よい)","p":"ai","m":{"az":"yaxşı","en":"good","ru":"хороший"},"n":{"az":"İ-sifətdir, lakin dəyişən formaları よい əsasından yaranır: よくない, よかった.","en":"An i-adjective whose inflected forms use よい: よくない, よかった.","ru":"И-прилагательное, изменяемые формы которого образуются от よい: よくない, よかった."}},"いう":{"b":"という","p":"ex","m":{"az":"adlı, deyilən","en":"called, named","ru":"под названием"},"n":{"az":"N という名前 = N adlı ad: 「かぐや」という名前 = «Kaquya» adı.","en":"N という名前 = the name \"N\".","ru":"N という名前 = имя «N»."}},"いつ":{"b":"いつ","p":"pr","m":{"az":"nə vaxt","en":"when","ru":"когда"},"n":{"az":"Adətən に qəbul etmir: いつ行きますか.","en":"Usually takes no に: いつ行きますか.","ru":"Обычно употребляется без に: いつ行きますか."}},"うれしい":{"b":"嬉しい (うれしい)","p":"ai","m":{"az":"sevincli, şad","en":"happy, glad","ru":"радостный, довольный"},"n":{"az":"い sifətidir, うれし bağlayıcı və ya başqa forma yaratmaq üçün əsasdır.","en":"An i-adjective, with うれし as the stem used to form other expressions.","ru":"Прилагательное на い, うれし - основа для образования других форм."}},"おいしい":{"b":"おいしい","p":"ai","m":{"az":"dadlı","en":"delicious, tasty","ru":"вкусный"},"n":{"az":"い-sifətdir: おいしくない = dadlı deyil.","en":"An i-adjective: おいしくない = not tasty.","ru":"Прилагательное на い: おいしくない = невкусный."}},"おなか":{"b":"おなか","p":"n","m":{"az":"qarın","en":"stomach, belly","ru":"живот"},"n":{"az":"おなかがすく “acmaq”, おなかがいっぱい isə “tox olmaq” deməkdir.","en":"おなかがすく means “get hungry,” and おなかがいっぱい means “be full.”","ru":"おなかがすく означает «проголодаться», а おなかがいっぱい означает «быть сытым»."}},"おにぎり":{"b":"おにぎり","p":"n","m":{"az":"düyü topası, onigiri","en":"rice ball, onigiri","ru":"онигири, рисовый шарик"}},"おもちゃ":{"b":"おもちゃ","p":"n","m":{"az":"oyuncaq","en":"toy","ru":"игрушка"}},"お母さん":{"b":"お母さん (おかあさん)","p":"n","m":{"az":"ana","en":"mother; mom","ru":"мама; мать"},"n":{"az":"Anaya müraciətdə və başqasının anası haqqında işlənir; kənar şəxslərə öz anandan danışarkən adətən 母 deyilir.","en":"Used to address your mother or refer to someone else's; use 母 for your own mother when speaking to outsiders.","ru":"Используется при обращении к маме или о чужой матери; о своей матери посторонним обычно говорят 母."}},"お父さん":{"b":"お父さん (おとうさん)","p":"n","m":{"az":"ata","en":"father; dad","ru":"папа; отец"},"n":{"az":"Ataya müraciətdə və başqasının atası haqqında işlənir; kənar şəxslərə öz atandan danışarkən adətən 父 deyilir.","en":"Used to address your father or refer to someone else's; use 父 for your own father when speaking to outsiders.","ru":"Используется при обращении к папе или о чужом отце; о своём отце посторонним обычно говорят 父."}},"お祭り":{"b":"お祭り (おまつり)","p":"n","m":{"az":"bayram; festival","en":"festival; celebration","ru":"праздник; фестиваль"},"n":{"az":"お nəzakət bildirən ön şəkilçidir; 祭り də işlənir.","en":"お is a polite prefix; 祭り is also used.","ru":"お является вежливой приставкой; также употребляется 祭り."}},"か":{"b":"か","p":"pt","m":{"az":"sual hissəciyi","en":"question particle","ru":"вопросительная частица"},"n":{"az":"Cümlənin sonuna gəlir və onu suala çevirir: 学生ですか = Tələbəsən? Yaponcada sual işarəsi əvəzinə adətən 。 yazılır.","en":"Goes at the end and turns the sentence into a question: 学生ですか = Are you a student? Japanese usually writes 。 instead of ?.","ru":"Ставится в конце и делает предложение вопросом: 学生ですか = Вы студент? Обычно пишут 。, а не ?."}},"かく":{"b":"かく","p":"v","m":{"az":"yazmaq, çəkmək","en":"to write, to draw","ru":"писать, рисовать"},"n":{"az":"Yazmaq 書く, şəkil çəkmək isə 描く ilə yazılır; hər ikisinin て forması かいて-dir.","en":"Writing uses 書く and drawing uses 描く; both have the て-form かいて.","ru":"Для письма используется 書く, для рисования 描く; форма на て у обоих: かいて."}},"かける":{"b":"掛ける (かける)","p":"v","m":{"az":"asmaq; qoymaq","en":"hang; put on","ru":"вешать; ставить"},"n":{"az":"Təsirli feldir: 電話をかける zəng etmək, 火にかける oda qoymaq, 声をかける səslənmək deməkdir.","en":"A transitive verb: 電話をかける means make a call, 火にかける put over heat, and 声をかける call out to someone.","ru":"Переходный глагол: 電話をかける значит позвонить, 火にかける поставить на огонь, 声をかける обратиться к кому-либо."}},"かばん":{"b":"鞄 (かばん)","p":"n","m":{"az":"çanta","en":"bag","ru":"сумка"}},"かぶる":{"b":"被る (かぶる)","p":"v","m":{"az":"başa taxmaq; örtmək","en":"to wear on the head; to cover","ru":"надевать на голову; покрывать"},"n":{"az":"帽子をかぶる papaq taxmaq, かぶっています isə taxmış vəziyyətdə olmaq deməkdir.","en":"帽子をかぶる means to put on a hat, while かぶっています describes wearing it.","ru":"帽子をかぶる означает надеть шляпу, а かぶっています - быть в шляпе."}},"から":{"b":"から","p":"pt","m":{"az":"-dan, -dən (haradan)","en":"from","ru":"из, от"},"n":{"az":"Başlanğıc nöqtəsini göstərir: 月から来ました = Aydan gəldim.","en":"Marks the starting point: 月から来ました = I came from the Moon.","ru":"Указывает исходную точку: 月から来ました = Я прилетела с Луны."}},"かわり":{"b":"代わり (かわり)","p":"n","m":{"az":"əvəz; yerinə","en":"substitute; replacement","ru":"замена; вместо"},"n":{"az":"〜の代わりに kiminsə və ya nəyinsə əvəzinə deməkdir.","en":"〜の代わりに means instead of someone or something.","ru":"〜の代わりに означает вместо кого-либо или чего-либо."}},"が":{"b":"が","p":"pt","m":{"az":"subyekt hissəciyi","en":"subject marker","ru":"частица подлежащего"},"n":{"az":"Hərəkəti edən və ya mövcud olan şeyi göstərir: 先生が来ました = müəllim gəldi. Yeni məlumatı vurğulayır; は isə artıq bəlli mövzunu.","en":"Marks who does the action or what exists: 先生が来ました = a teacher came. Introduces new information, while は marks a known topic.","ru":"Отмечает деятеля или то, что существует: 先生が来ました = пришёл учитель. Вводит новую информацию; は – уже известную тему."}},"ここ":{"b":"ここ","p":"pr","m":{"az":"bura; burada","en":"here; this place","ru":"здесь; это место"},"n":{"az":"Danışana yaxın yeri bildirir.","en":"Refers to a place near the speaker.","ru":"Указывает на место рядом с говорящим."}},"こそ":{"b":"こそ","p":"pt","m":{"az":"məhz; elə","en":"precisely; the very","ru":"именно; как раз"},"n":{"az":"Vurğu yaradır: 今年こそ = məhz bu il; こちらこそ = mən də sizə.","en":"Adds emphasis: 今年こそ = this year for sure; こちらこそ = likewise on my part.","ru":"Усиливает выделение: 今年こそ = именно в этом году; こちらこそ = это я вас благодарю."}},"こと":{"b":"こと","p":"n","m":{"az":"iş; hadisə; məsələ","en":"thing; matter; event","ru":"дело; событие; обстоятельство"},"n":{"az":"Felə qoşularaq hərəkəti isimləşdirir: 読むこと oxumaq hərəkəti.","en":"It nominalizes verbs: 読むこと means the act of reading.","ru":"Превращает глагол в существительное: 読むこと означает чтение."}},"こわす":{"b":"壊す (こわす)","p":"v","m":{"az":"sındırmaq; xarab etmək","en":"to break; to damage","ru":"ломать; портить"},"n":{"az":"Təsirli feldir; 壊れる isə öz-özünə sınmaq və ya xarab olmaq deməkdir.","en":"Transitive verb; 壊れる is its intransitive counterpart.","ru":"Переходный глагол; 壊れる является его непереходной парой."}},"こわれる":{"b":"壊れる (こわれる)","p":"v","m":{"az":"xarab olmaq, sınmaq","en":"to break, to become damaged","ru":"ломаться, выходить из строя"},"n":{"az":"壊れる təsirsiz feildir, 壊す isə nəyisə sındırmaq deməkdir.","en":"壊れる is intransitive; 壊す means to break something.","ru":"壊れる непереходный глагол, а 壊す означает сломать что-либо."}},"ごはん":{"b":"ご飯 (ごはん)","p":"n","m":{"az":"yemək; düyü","en":"meal; rice","ru":"еда; рис"}},"しか":{"b":"しか","p":"pt","m":{"az":"yalnız, ancaq","en":"only, nothing but","ru":"только, лишь"},"n":{"az":"Həmişə inkarla işlənir: 一つしかありません = cəmi bir dənə var.","en":"Used with a negative predicate: 一つしかありません = there is only one.","ru":"Употребляется с отрицанием: 一つしかありません = есть только одна штука."}},"しかし":{"b":"しかし (しかし)","p":"cj","m":{"az":"lakin; ancaq","en":"however; nevertheless","ru":"однако; тем не менее"},"n":{"az":"Əvvəlki fikrə zidd olan yeni fikri təqdim edir.","en":"Introduces a statement contrasting with the previous one.","ru":"Вводит мысль, противопоставленную предыдущей."}},"しっぽ":{"b":"尻尾 (しっぽ)","p":"n","m":{"az":"quyruq","en":"tail","ru":"хвост"}},"じゃあ":{"b":"じゃあ (じゃあ)","p":"cj","m":{"az":"onda; elə isə","en":"then; well then","ru":"тогда; ну что ж"},"n":{"az":"Danışıq dilində işlənir; daha rəsmi qarşılığı では-dir.","en":"Conversational expression; では is a more formal equivalent.","ru":"Разговорное выражение; более формальный вариант では."}},"すぎる":{"b":"過ぎる (すぎる)","p":"v","m":{"az":"keçmək, həddi aşmaq","en":"to pass, to exceed","ru":"проходить, превышать"},"n":{"az":"Feildən və ya sifətdən sonra 〜すぎる həddindən artıq olmağı bildirir.","en":"After a verb or adjective stem, 〜すぎる means doing or being something too much.","ru":"После основы глагола или прилагательного 〜すぎる означает чрезмерность."}},"すく":{"b":"すく (空く)","p":"v","m":{"az":"acmaq, boşalmaq","en":"to become empty, to get hungry","ru":"опустеть, проголодаться"},"n":{"az":"I qrup feldir: おなかがすきました = acdım; 空く həm də boşalmaq deməkdir.","en":"A Group 1 verb: おなかがすきました = I got hungry; 空く can also mean to become empty.","ru":"Глагол I группы: おなかがすきました = я проголодался; 空く также означает опустеть."}},"すぐ":{"b":"すぐ","p":"ad","m":{"az":"tez, dərhal","en":"soon, immediately","ru":"сразу, скоро"},"n":{"az":"すぐに = dərhal.","en":"すぐに = right away.","ru":"すぐに = сразу."}},"する":{"b":"する","p":"v","m":{"az":"etmək; (səs, iy) gəlmək","en":"to do; (a sound) to be heard","ru":"делать; (о звуке) слышаться"},"n":{"az":"Ən çox işlənən feil. 音がしました = səs gəldi. 〜ようとしました = ...-mağa çalışdı.","en":"Most common verb. 音がしました = there was a sound. 〜ようとしました = tried to ...","ru":"Самый частый глагол. 音がしました = раздался звук. 〜ようとしました = попытался ..."}},"そう":{"b":"そう","p":"ad","m":{"az":"elə; belə","en":"so; that way","ru":"так"},"n":{"az":"そうです təsdiq, そうします isə deyilən şəkildə hərəkət etməyi bildirir.","en":"そうです confirms something; そうします means to do it that way.","ru":"そうです выражает подтверждение, а そうします означает сделать именно так."}},"そこ":{"b":"そこ","p":"pr","m":{"az":"ora","en":"there","ru":"там"},"n":{"az":"Dinləyiciyə yaxın və ya söhbətdə artıq qeyd olunan yeri göstərir.","en":"Refers to a place near the listener or already mentioned.","ru":"Обозначает место рядом с собеседником или уже упомянутое место."}},"そして":{"b":"そして","p":"cj","m":{"az":"və, sonra","en":"and, then","ru":"и, затем"}},"そば":{"b":"そば","p":"n","m":{"az":"yan, yaxınlıq","en":"side, nearby","ru":"рядом, около"},"n":{"az":"N の そば = N-in yanında.","en":"N の そば = beside N.","ru":"N の そば = рядом с N."}},"たくさん":{"b":"たくさん","p":"ad","m":{"az":"çox; çoxlu","en":"many; much; a lot","ru":"много"},"n":{"az":"İsimlə たくさんの本, fellə isə たくさん食べる şəklində işlənir.","en":"Use たくさんの本 with a noun and たくさん食べる with a verb.","ru":"С существительным употребляется たくさんの本, с глаголом たくさん食べる."}},"だ":{"b":"だ (だ)","p":"cp","m":{"az":"-dır, -dir; olmaq","en":"to be; is, am, are","ru":"быть; являться"},"n":{"az":"なら şərt formasıdır: 学生なら, əgər tələbədirsə.","en":"なら is a conditional form: 学生なら means if someone is a student.","ru":"なら является условной формой: 学生なら означает если он студент."}},"だけ":{"b":"だけ","p":"pt","m":{"az":"yalnız, ancaq","en":"only, just","ru":"только"},"n":{"az":"一度だけ = bircə dəfə; まんなかの星だけ = yalnız ortadakı ulduz.","en":"一度だけ = just once.","ru":"一度だけ = только один раз."}},"つく":{"b":"つく (着く)","p":"v","m":{"az":"çatmaq, yetişmək","en":"to arrive, to reach","ru":"прибывать, добираться"},"n":{"az":"I qrup feldir: 駅に着く = stansiyaya çatmaq; つきませんでした = çatmadı.","en":"A Group 1 verb: 駅に着く = to arrive at the station; つきませんでした = did not arrive.","ru":"Глагол I группы: 駅に着く = прибыть на станцию; つきませんでした = не прибыл."}},"つける":{"b":"付ける (つける)","p":"v","m":{"az":"qoymaq (ad), taxmaq","en":"to give (a name), attach","ru":"давать (имя), прикреплять"},"n":{"az":"名前をつける = ad qoymaq.","en":"名前をつける = give a name.","ru":"名前をつける = дать имя."}},"つもり":{"b":"つもり (つもり)","p":"n","m":{"az":"niyyət; fikir","en":"intention; plan","ru":"намерение; план"},"n":{"az":"Felın lüğət forması + つもりです niyyəti bildirir: 行くつもりです.","en":"Verb dictionary form + つもりです expresses intention: 行くつもりです.","ru":"Словарная форма глагола + つもりです выражает намерение: 行くつもりです."}},"で":{"b":"で","p":"pt","m":{"az":"-da/-də (hərəkətin yeri); ilə (vasitə)","en":"at, in (place of action); with, by (means)","ru":"в, на (место действия); с помощью"},"n":{"az":"Hərəkətin baş verdiyi yer: 山で竹を切る = dağda bambuk kəsmək; 庭で泣く = bağçada ağlamaq. Vasitə: 両手で = iki əllə. Varlıq üçün に işlənir, hərəkət üçün で.","en":"Place where an action happens: 山で = on the mountain; means: 両手で = with both hands. Existence uses に, actions use で.","ru":"Место действия: 山で = в горах; средство: 両手で = обеими руками. Для существования – に, для действия – で."}},"できる":{"b":"できる","p":"v","m":{"az":"bacarmaq; hazır olmaq","en":"be able to; be ready","ru":"мочь; быть готовым"},"n":{"az":"Bacarığı 日本語ができる, tamamlanmanı isə ご飯ができる kimi ifadə edir.","en":"Expresses ability in 日本語ができる and completion in ご飯ができる.","ru":"Выражает умение в 日本語ができる и готовность в ご飯ができる."}},"です":{"b":"です","p":"cp","m":{"az":"-dır, -dir (nəzakətli)","en":"is, am, are (polite)","ru":"есть, является (вежл.)"},"n":{"az":"İsmin sonunda gəlir: 学生です = Tələbəyəm / tələbədir. İndiki zaman, təsdiq, nəzakətli forma. Şəxs bildirmir: kontekstdən anlaşılır.","en":"Ends a noun sentence: 学生です = I am / he is a student. Present, affirmative, polite. It shows no person: context tells.","ru":"Завершает именное предложение: 学生です = я студент / он студент. Настоящее время, утверждение, вежливо. Лицо не выражает."}},"でも":{"b":"でも","p":"cj","m":{"az":"amma, lakin","en":"but","ru":"но"},"n":{"az":"Cümlənin əvvəlində gəlir və əvvəlki fikrə zidd fikir gətirir.","en":"Starts a sentence and introduces a contrast.","ru":"Начинает предложение и вводит противопоставление."}},"と":{"b":"と","p":"pt","m":{"az":"ilə; (sitat) deyə","en":"and, with; (quote marker)","ru":"и, с; (цитата)"},"n":{"az":"İki mənası var: 1) おじいさんとおばあさん = baba və nənə; 2) sitatdan sonra: 「森です」と言いました = «Moriyəm» dedi. 〜と思う = ...deyə düşünmək. Feildən sonra (開けると) isə 'edəndə, ...-ınca' deməkdir.","en":"Two main uses: 1) 'and' between nouns; 2) after a quote: 「…」と言いました = said \"…\". After a verb (開けると) it means 'when/as soon as'.","ru":"Основные значения: 1) 'и' между существительными; 2) после цитаты: 「…」と言いました = сказал «…». После глагола (開けると) – 'когда/как только'."}},"ところ":{"b":"所 (ところ)","p":"n","m":{"az":"yer; məqam; an","en":"place; point; moment","ru":"место; момент"},"n":{"az":"Vるところ başlanmaq üzrə olan, Vているところ davam edən, Vたところ isə yenicə bitmiş hərəkətdir.","en":"Vるところ means about to do, Vているところ means in progress, and Vたところ means just finished.","ru":"Vるところ означает собираюсь сделать, Vているところ процесс, а Vたところ только что закончил."}},"とても":{"b":"とても","p":"ad","m":{"az":"çox","en":"very","ru":"очень"}},"なくなる":{"b":"なくなる (なくなる)","p":"v","m":{"az":"yoxa çıxmaq; tükənmək; bitmək","en":"to disappear; to run out; to be gone","ru":"исчезать; заканчиваться; пропадать"},"n":{"az":"物がなくなる bir şeyin yoxa çıxmasıdır, なくす isə onu itirməkdir.","en":"物がなくなる means something disappears, while なくす means to lose it.","ru":"物がなくなる означает что-то пропадает, а なくす означает потерять это."}},"なぜ":{"b":"なぜ (なぜ)","p":"ad","m":{"az":"niyə; nə üçün","en":"why; for what reason","ru":"почему; по какой причине"},"n":{"az":"Səbəb soruşur; どうして ilə yaxındır, lakin bir qədər rəsmidir.","en":"Asks for a reason; slightly more formal than どうして.","ru":"Спрашивает о причине; немного формальнее, чем どうして."}},"なる":{"b":"なる","p":"v","m":{"az":"olmaq, çevrilmək","en":"to become","ru":"становиться"},"n":{"az":"N/na-sifət + に なる; i-sifət: い → く なる (大きくなる = böyümək).","en":"N/na-adj + に なる; i-adj: い → く なる (大きくなる = grow big).","ru":"N/na-прил. + に なる; i-прил.: い → く なる (大きくなる = вырасти)."}},"に":{"b":"に","p":"pt","m":{"az":"-a/-ə; -da/-də; -ı (hədəf)","en":"to; at, in; (target)","ru":"в, на; к (цель)"},"n":{"az":"Çoxmənalı hissəcik: yer (教室の前に立つ = sinifin qabağında dayanmaq), istiqamət/hədəf (大学に来る = universitetə gəlmək), zaman (二年前に = iki il əvvəl), nəticə (静かになる). Mənanı feil müəyyən edir.","en":"Many uses: location of existence/position, destination or target, a point in time, the result of a change. The verb decides which.","ru":"Многозначная частица: место (стоять перед), направление/цель (прийти в университет), время (два года назад), результат изменения. Значение задаёт глагол."}},"にげる":{"b":"逃げる (にげる)","p":"v","m":{"az":"qaçmaq; canını qurtarmaq","en":"to run away; to escape","ru":"убегать; спасаться бегством"},"n":{"az":"逃げる təhlükədən uzaqlaşmaqdır; 逃がす isə kimisə qaçırmaq və ya buraxmaqdır.","en":"逃げる means to escape; 逃がす means to let someone escape.","ru":"逃げる означает убегать; 逃がす означает дать кому-либо убежать."}},"ね":{"b":"ね","p":"pt","m":{"az":"elə deyilmi?; hə?","en":"right?; isn't it?","ru":"правда?; ведь"},"n":{"az":"Cümlə sonunda təsdiq və ortaq hiss bildirir, məsələn 寒いですね, əmri yumşaldır, məsələn 来てね, danışıqda isə 私はね kimi diqqət çəkir.","en":"At sentence end it seeks agreement or shares a feeling, as in 寒いですね, softens requests, as in 来てね, and conversationally draws attention, as in 私はね.","ru":"В конце фразы выражает ожидание согласия или общее чувство, как в 寒いですね, смягчает просьбу, как в 来てね, и привлекает внимание, как в 私はね."}},"の":{"b":"の","p":"pt","m":{"az":"-ın, -in (yiyəlik); iki ismi bağlayır","en":"of, -'s; links two nouns","ru":"связывает два существительных (род. падеж)"},"n":{"az":"N1 の N2: N1 N2-ni təyin edir. さくら大学の学生 = Sakura Universitetinin tələbəsi; ロボットの先生 = robot müəllim (növ bildirir).","en":"N1 の N2: N1 describes N2. さくら大学の学生 = a student of Sakura University; ロボットの先生 = a robot teacher (kind).","ru":"N1 の N2: N1 определяет N2. さくら大学の学生 = студент университета Сакура; ロボットの先生 = учитель-робот (вид)."}},"は":{"b":"は (wa)","p":"pt","m":{"az":"mövzu hissəciyi","en":"topic marker","ru":"частица темы"},"n":{"az":"Cümlənin nədən bəhs etdiyini göstərir. Yazılışı は, amma hissəcik kimi 'wa' oxunur: わたしは = 'mənə gəlincə / mən'.","en":"Marks what the sentence is about. Written は but read 'wa' as a particle: わたしは = 'as for me'.","ru":"Отмечает, о чём предложение. Пишется は, но как частица читается 'wa': わたしは = 'что касается меня'."}},"ばん目":{"b":"番目 (ばんめ)","p":"n","m":{"az":"sıra yeri; -ıncı","en":"ordinal position; number in order","ru":"место по порядку; -й по счёту"},"n":{"az":"Rəqəmdən sonra gəlir: 一番目, 二番目, 三番目.","en":"Follows a number to indicate order: 一番目, 二番目, 三番目.","ru":"Ставится после числа для обозначения порядка: 一番目, 二番目, 三番目."}},"ひみつ":{"b":"秘密 (ひみつ)","p":"n","m":{"az":"sirr; gizli məlumat","en":"secret","ru":"секрет; тайна"},"n":{"az":"秘密の söz birləşməsi gizli mənasını verir.","en":"秘密の means secret or confidential before a noun.","ru":"秘密の перед существительным означает тайный или секретный."}},"びっくり":{"b":"びっくり","p":"ad","m":{"az":"təəccüb; diksinmə","en":"surprise; startlement","ru":"удивление; испуг"},"n":{"az":"びっくりする təəccüblənmək və ya qəfil diksinmək deməkdir.","en":"びっくりする means to be surprised or startled.","ru":"びっくりする означает удивиться или вздрогнуть от неожиданности."}},"ふく":{"b":"吹く (ふく)","p":"v","m":{"az":"əsmək; üfürmək","en":"to blow; to blow wind","ru":"дуть; веять"},"n":{"az":"風が吹く külək əsmək deməkdir; 拭く isə silmək mənasında başqa feldir.","en":"風が吹く means the wind blows; 拭く is a different verb meaning to wipe.","ru":"風が吹く означает дует ветер; 拭く является другим глаголом со значением вытирать."}},"へ":{"b":"へ (e)","p":"pt","m":{"az":"-a/-ə (istiqamət)","en":"to, toward","ru":"к, в (направление)"},"n":{"az":"İstiqamət bildirir: 家へ帰る = evə qayıtmaq. Hissəcik kimi 'e' oxunur.","en":"Shows direction: 家へ帰る = go home. Read 'e' as a particle.","ru":"Направление: 家へ帰る = вернуться домой. Как частица читается 'e'."}},"ほう":{"b":"方 (ほう)","p":"n","m":{"az":"tərəf, istiqamət, seçim","en":"side, direction, option","ru":"сторона, направление, вариант"},"n":{"az":"〜のほう müqayisədə üstün tutulan tərəfi bildirə bilər.","en":"〜のほう can indicate the preferred side in a comparison.","ru":"〜のほう может указывать на предпочтительный вариант при сравнении."}},"ほか":{"b":"他 (ほか)","p":"n","m":{"az":"başqa; digəri","en":"other; elsewhere","ru":"другой; остальное"},"n":{"az":"ほかの人 başqa adam, ほかに isə əlavə olaraq deməkdir.","en":"ほかの人 means another person, and ほかに means additionally.","ru":"ほかの人 означает другой человек, а ほかに - кроме того."}},"ほす":{"b":"欲しがる (ほしがる)","p":"v","m":{"az":"istəmək; əldə etməyə can atmaq","en":"to want; to show desire for","ru":"хотеть; проявлять желание получить"},"n":{"az":"ほしがりました, 欲しがる felinin keçmiş formasıdır və başqasının istəyini bildirir.","en":"ほしがりました is the past of 欲しがる, used to describe another person's desire.","ru":"ほしがりました является прошедшей формой 欲しがる и описывает желание другого человека."}},"まず":{"b":"まず","p":"ad","m":{"az":"əvvəlcə; ilk növbədə","en":"first; to begin with","ru":"сначала; прежде всего"}},"まだ":{"b":"まだ","p":"ad","m":{"az":"hələ","en":"still, yet","ru":"ещё"}},"まで":{"b":"まで","p":"pt","m":{"az":"qədər, hətta","en":"until, as far as, even","ru":"до, даже"},"n":{"az":"Zaman və məkan həddini bildirir: 五時まで “saat beşə qədər”, 駅まで “stansiyaya qədər”; təəccüblü əlavəni də vurğulayır: 子どもまで “hətta uşaqlar”.","en":"Marks a time or place limit, as in 五時まで “until five” and 駅まで “as far as the station,” and surprising inclusion, as in 子どもまで “even children.”","ru":"Обозначает предел времени или места: 五時まで «до пяти», 駅まで «до станции», а также неожиданное включение: 子どもまで «даже дети»."}},"みんな":{"b":"みんな","p":"n","m":{"az":"hamı, hamısı","en":"everyone, all","ru":"все"}},"むかしむかし":{"b":"昔々 (むかしむかし)","p":"ex","m":{"az":"biri var idi, biri yox idi","en":"once upon a time","ru":"давным-давно"},"n":{"az":"Yapon nağıllarının ənənəvi başlanğıcı.","en":"The traditional opening of Japanese tales.","ru":"Традиционное начало японских сказок."}},"も":{"b":"も","p":"pt","m":{"az":"də, da (həmçinin)","en":"also, too","ru":"тоже, также"},"n":{"az":"は-nin yerinə gəlir: ケンさんも = 'Ken də'. は ilə birlikdə işlənmir.","en":"Replaces は: ケンさんも = 'Ken too'. Not used together with は.","ru":"Ставится вместо は: ケンさんも = 'Кен тоже'. Вместе с は не используется."}},"もう":{"b":"もう","p":"ad","m":{"az":"daha; artıq","en":"more; already","ru":"ещё; уже"},"n":{"az":"もう一度 = bir daha.","en":"もう一度 = once more.","ru":"もう一度 = ещё раз."}},"もっと":{"b":"もっと","p":"ad","m":{"az":"daha, daha çox","en":"more","ru":"больше, ещё"}},"や":{"b":"や","p":"pt","m":{"az":"və, ... kimi","en":"and, things such as","ru":"и, например"},"n":{"az":"や tam olmayan siyahı yaradır: 犬や猫（など）; nida və çağırışda da işlənir: おや、太郎や.","en":"や gives a non-exhaustive list, 犬や猫（など）, and also appears in exclamations or calls, おや、太郎や.","ru":"や обозначает неполный перечень, 犬や猫（など）, а также встречается в восклицаниях и обращениях: おや、太郎や."}},"やっと":{"b":"やっと","p":"ad","m":{"az":"nəhayət, güclə","en":"finally, barely","ru":"наконец, едва"},"n":{"az":"Uzun gözləmə və ya çətinlikdən sonra nəticəni, bəzən də güclə çatmağı bildirir.","en":"Indicates a result after waiting or effort, or sometimes barely managing something.","ru":"Обозначает результат после ожидания или усилий, иногда достижение чего-либо с трудом."}},"やる":{"b":"やる","p":"v","m":{"az":"etmək; yerinə yetirmək","en":"to do; to carry out","ru":"делать; выполнять"},"n":{"az":"する felinin daha qeyri-rəsmi variantıdır və kiməsə nəsə vermək mənasında da işlənir.","en":"A more informal alternative to する; it can also mean to give something to someone or an animal.","ru":"Более разговорный вариант する; также может означать давать кому-либо или животному."}},"よ":{"b":"よ","p":"pt","m":{"az":"cümləsonu vurğu ədatı","en":"sentence-final emphasis particle","ru":"конечная усилительная частица"},"n":{"az":"Cümlənin sonunda yeni məlumatı, əminliyi və ya xəbərdarlığı vurğulayır: ここですよ “Buradadır”, 危ないよ “Ehtiyatlı ol”; 行こうよ kimi ifadələrdə çağırışı gücləndirir.","en":"At sentence end, it stresses information, assurance, or warning, as in ここですよ “It's here” and 危ないよ “Watch out,” and strengthens invitations such as 行こうよ “Let's go.”","ru":"В конце предложения подчёркивает сообщение, уверенность или предупреждение: ここですよ «Это здесь», 危ないよ «Осторожно», а также усиливает призыв: 行こうよ «Пойдём»."}},"わら":{"b":"藁 (わら)","p":"n","m":{"az":"saman","en":"straw","ru":"солома"}},"を":{"b":"を (o)","p":"pt","m":{"az":"təsirlik hissəcik (-ı, -i)","en":"object marker","ru":"частица прямого объекта"},"n":{"az":"Feilin təsir etdiyi əşyanı göstərir: かばんを持つ = çantanı tutmaq. Yazılışı を, oxunuşu 'o'.","en":"Marks the direct object: かばんを持つ = hold a bag. Written を, read 'o'.","ru":"Отмечает прямое дополнение: かばんを持つ = держать сумку. Пишется を, читается 'o'."}},"エンジン":{"b":"エンジン (エンジン)","p":"n","m":{"az":"mühərrik","en":"engine","ru":"двигатель"}},"オオカミ":{"b":"狼 (おおかみ)","p":"n","m":{"az":"canavar","en":"wolf","ru":"волк"}},"キャンプ":{"b":"キャンプ (キャンプ)","p":"n","m":{"az":"kempinq; çadır düşərgəsi","en":"camping; camp","ru":"кемпинг; лагерь"},"n":{"az":"キャンプする təbiətdə düşərgə qurmaq deməkdir.","en":"キャンプする means to go camping.","ru":"キャンプする означает отдыхать в палаточном лагере."}},"スープ":{"b":"スープ (スープ)","p":"n","m":{"az":"şorba","en":"soup","ru":"суп"}},"ソラ":{"b":"ソラ","p":"nm","m":{"az":"Sora","en":"Sora","ru":"Сора"}},"タロウ":{"b":"タロウ (たろう)","p":"nm","m":{"az":"Taro, kişi adı","en":"Tarō, a male name","ru":"Таро, мужское имя"}},"ドア":{"b":"ドア","p":"n","m":{"az":"qapı","en":"door","ru":"дверь"}},"プール":{"b":"プール (プール)","p":"n","m":{"az":"üzgüçülük hovuzu","en":"swimming pool","ru":"бассейн"}},"ボタン":{"b":"ボタン","p":"n","m":{"az":"düymə","en":"button","ru":"кнопка; пуговица"},"n":{"az":"Həm cihaz düyməsi, həm də geyim düyməsi üçün işlənir.","en":"Used for both device buttons and clothing buttons.","ru":"Употребляется для кнопок устройств и пуговиц одежды."}},"ミオ":{"b":"ミオ (ミオ)","p":"nm","m":{"az":"Mio; şəxs adı","en":"Mio; personal name","ru":"Мио; личное имя"}},"ミオたち":{"b":"ミオたち (ミオたち)","p":"n","m":{"az":"Mio və digərləri","en":"Mio and the others","ru":"Мио и остальные"},"n":{"az":"たち şəxs adından sonra həmin şəxsin daxil olduğu qrupu bildirir.","en":"たち after a person's name means that person and their group.","ru":"たち после имени обозначает этого человека и его группу."}},"ユキ":{"b":"ユキ","p":"nm","m":{"az":"Yuki (qız adı, 'qar' deməkdir)","en":"Yuki (girl's name, means 'snow')","ru":"Юки (имя, значит 'снег')"}},"ロケット":{"b":"ロケット (ロケット)","p":"n","m":{"az":"raket; kosmik raket","en":"rocket; space rocket","ru":"ракета; космическая ракета"}},"一つ":{"b":"一つ (ひとつ)","p":"n","m":{"az":"bir (dənə)","en":"one (thing)","ru":"одна (штука)"},"n":{"az":"Ümumi sayğac: 一つ, 二つ, 三つ.","en":"General counter: 一つ, 二つ, 三つ.","ru":"Общий счёт: 一つ, 二つ, 三つ."}},"一ばん":{"b":"一番 (いちばん)","p":"ad","m":{"az":"ən çox; ən; birinci","en":"most; best; first","ru":"больше всего; самый; первый"},"n":{"az":"Sifətlə ən yüksək dərəcəni bildirir: 一番大きい.","en":"With an adjective, indicates the superlative: 一番大きい.","ru":"С прилагательным обозначает превосходную степень: 一番大きい."}},"一回":{"b":"一回 (いっかい)","p":"n","m":{"az":"bir dəfə","en":"once","ru":"один раз"},"n":{"az":"いっかい kimi oxunur.","en":"Read as いっかい.","ru":"Читается いっかい."}},"一度":{"b":"一度 (いちど)","p":"n","m":{"az":"bir dəfə","en":"once","ru":"один раз"}},"一緒":{"b":"一緒 (いっしょ)","p":"n","m":{"az":"birlik, bir yerdə olma","en":"being together","ru":"совместность, пребывание вместе"},"n":{"az":"一緒に “birlikdə” deməkdir: 友達と一緒に “dostla birlikdə”.","en":"一緒に means “together,” as in 友達と一緒に “together with a friend.”","ru":"一緒に означает «вместе»: 友達と一緒に «вместе с другом»."}},"三":{"b":"三 (さん)","p":"nu","m":{"az":"üç","en":"three","ru":"три"}},"三びき":{"b":"三匹 (さんびき)","p":"nu","m":{"az":"üç heyvan; üç ədəd kiçik heyvan","en":"three small animals","ru":"три небольших животных"},"n":{"az":"匹 sayğacında səslər dəyişir: 一匹 いっぴき, 二匹 にひき, 三匹 さんびき.","en":"The 匹 counter changes pronunciation: 一匹 いっぴき, 二匹 にひき, 三匹 さんびき.","ru":"У счётного суффикса 匹 меняется произношение: 一匹 いっぴき, 二匹 にひき, 三匹 さんびき."}},"三日":{"b":"三日 (みっか)","p":"nu","m":{"az":"ayın üçüncü günü, üç gün","en":"third day of the month, three days","ru":"третье число месяца, три дня"},"n":{"az":"Tarix və müddət bildirir, 三日 みっか oxunur.","en":"Used for a date or duration, pronounced みっか.","ru":"Обозначает дату или длительность, читается みっか."}},"上":{"b":"上 (うえ)","p":"n","m":{"az":"üst","en":"top, above","ru":"верх, на"},"n":{"az":"N の 上 = N-in üstü.","en":"N の 上 = on top of N.","ru":"N の 上 = на N."}},"並べる":{"b":"並べる (ならべる)","p":"v","m":{"az":"düzmək; yan-yana yerləşdirmək","en":"to arrange; to line up","ru":"расставлять; выстраивать"},"n":{"az":"他動詞-dir; qarşılığı 並ぶ, yəni düzülməkdir.","en":"A transitive verb; its intransitive pair is 並ぶ.","ru":"Переходный глагол; непереходная пара 並ぶ."}},"中":{"b":"中 (なか)","p":"n","m":{"az":"iç","en":"inside","ru":"внутри"},"n":{"az":"N の 中 = N-in içi.","en":"N の 中 = inside N.","ru":"N の 中 = внутри N."}},"乗る":{"b":"乗る (のる)","p":"v","m":{"az":"minmək","en":"board, ride","ru":"садиться в транспорт, ехать"},"n":{"az":"Nəqliyyat vasitəsi に ilə işlənir: 電車に乗る “qatara minmək”.","en":"The vehicle takes に: 電車に乗る means “board a train.”","ru":"Транспорт обозначается с に: 電車に乗る «сесть в поезд»."}},"予定":{"b":"予定 (よてい)","p":"n","m":{"az":"plan; nəzərdə tutulan vaxt","en":"plan; schedule","ru":"план; расписание"},"n":{"az":"〜予定です planlaşdırılmış hərəkəti bildirir: 明日出発する予定です.","en":"〜予定です expresses a scheduled plan: 明日出発する予定です.","ru":"〜予定です обозначает запланированное действие: 明日出発する予定です."}},"二":{"b":"二 (に)","p":"nu","m":{"az":"iki","en":"two","ru":"два"}},"二ひき":{"b":"二匹 (にひき)","p":"nu","m":{"az":"iki heyvan; iki ədəd kiçik heyvan","en":"two small animals","ru":"два небольших животных"},"n":{"az":"匹 kiçik heyvanları sayır; 二匹 にひき, 三匹 さんびき, 六匹 ろっぴき oxunur.","en":"匹 counts small animals; 二匹 is にひき, 三匹 is さんびき, and 六匹 is ろっぴき.","ru":"匹 считает небольших животных; 二匹 читается にひき, 三匹 さんびき, 六匹 ろっぴき."}},"二人":{"b":"二人 (ふたり)","p":"n","m":{"az":"iki nəfər, ikisi","en":"two people","ru":"двое"},"n":{"az":"İnsan sayğacı: 一人 (ひとり), 二人 (ふたり), 三人 (さんにん).","en":"People counter: 一人, 二人, 三人.","ru":"Счёт людей: 一人, 二人, 三人."}},"今度":{"b":"今度 (こんど)","p":"n","m":{"az":"bu dəfə, gələn dəfə","en":"this time, next time","ru":"на этот раз, в следующий раз"},"n":{"az":"Kontekstdən asılı olaraq indiki və ya növbəti hadisəni bildirir.","en":"Depending on context, it refers to the present occasion or the next one.","ru":"В зависимости от контекста обозначает нынешний или следующий случай."}},"仕事":{"b":"仕事 (しごと)","p":"n","m":{"az":"iş","en":"work, job","ru":"работа"}},"休み":{"b":"休み (やすみ)","p":"n","m":{"az":"istirahət, istirahət günü","en":"rest, day off","ru":"отдых, выходной"}},"住む":{"b":"住む (すむ)","p":"v","m":{"az":"yaşamaq, məskunlaşmaq","en":"to live, to reside","ru":"жить, проживать"},"n":{"az":"住んで て-formadır, 場所に住む müəyyən yerdə yaşamaq deməkdir.","en":"住んで is the te-form, and 場所に住む means to live in a place.","ru":"住んで - форма на て, 場所に住む означает жить в определённом месте."}},"作る":{"b":"作る (つくる)","p":"v","m":{"az":"düzəltmək, yaratmaq","en":"to make","ru":"делать, создавать"},"n":{"az":"作ったのでした = (məlum oldu ki) düzəltmişdilər – izah bildirir.","en":"作ったのでした = (it turned out) they had made him.","ru":"作ったのでした = (оказалось) создали его."}},"使う":{"b":"使う (つかう)","p":"v","m":{"az":"istifadə etmək; işlətmək","en":"to use","ru":"использовать; пользоваться"},"n":{"az":"N を使う şəklində işlənir: パソコンを使う.","en":"Takes を for the object: パソコンを使う means to use a computer.","ru":"Используется с を для объекта: パソコンを使う означает пользоваться компьютером."}},"兄たち":{"b":"兄たち (あにたち)","p":"n","m":{"az":"böyük qardaşlarım; böyük qardaşlar","en":"older brothers; my older brothers","ru":"старшие братья; мои старшие братья"},"n":{"az":"兄 adətən öz böyük qardaşı üçün işlənir; たち cəm və ya qrup bildirir.","en":"兄 usually refers to one's own older brother; たち marks a plural or group.","ru":"兄 обычно обозначает собственного старшего брата; たち указывает на множественность или группу."}},"先生":{"b":"先生 (せんせい)","p":"n","m":{"az":"müəllim; həkim","en":"teacher; doctor","ru":"учитель; доктор"},"n":{"az":"Başqasına müraciət kimi işlənir (ミミ先生 = Mimi həkim). Özün haqqında 先生 demirsən, 教師 deyirsən.","en":"Used to address others (ミミ先生 = Doctor Mimi). Never about yourself – then you say 教師.","ru":"Используется как обращение (ミミ先生 = доктор Мими). О себе так не говорят – говорят 教師."}},"光る":{"b":"光る (ひかる)","p":"v","m":{"az":"parlamaq, işıq saçmaq","en":"to shine","ru":"светиться, сиять"},"n":{"az":"光るランプ = parlayan lampa: feil isimdən əvvəl təyin kimi gəlir.","en":"光るランプ = a glowing lamp: a verb before a noun describes it.","ru":"光るランプ = светящаяся лампа: глагол перед сущ. – определение."}},"入れる":{"b":"入れる (いれる)","p":"v","m":{"az":"içəri qoymaq; daxil etmək","en":"to put in; to insert","ru":"класть внутрь; вставлять"},"n":{"az":"Təsirlidir: 箱に入れる; təsirsiz qarşılığı 入る-dur.","en":"Transitive: 箱に入れる; its intransitive partner is 入る.","ru":"Переходный: 箱に入れる; непереходная пара: 入る."}},"全部":{"b":"全部 (ぜんぶ)","p":"n","m":{"az":"hamısı, bütün","en":"all, everything","ru":"всё, целиком"},"n":{"az":"全部で = ümumilikdə; 全部食べました = hamısını yedim.","en":"全部で = in total; 全部食べました = ate everything.","ru":"全部で = всего; 全部食べました = съел всё."}},"出す":{"b":"出す (だす)","p":"v","m":{"az":"çıxarmaq","en":"to take out","ru":"вынимать"}},"前":{"b":"前 (まえ)","p":"n","m":{"az":"qabaq, ön; əvvəl","en":"front; before","ru":"перед; раньше"},"n":{"az":"N の 前 = N-in qabağı. 二年前 = iki il əvvəl.","en":"N の 前 = in front of N. 二年前 = two years ago.","ru":"N の 前 = перед N. 二年前 = два года назад."}},"動く":{"b":"動く (うごく)","p":"v","m":{"az":"hərəkət etmək, işləmək","en":"to move, to operate","ru":"двигаться, работать"},"n":{"az":"I qrup feldir: 動きました = hərəkət etdi; 動かす = hərəkət etdirmək.","en":"A Group 1 verb: 動きました = moved; 動かす = to move something.","ru":"Глагол I группы: 動きました = двигался; 動かす = приводить в движение."}},"午後":{"b":"午後 (ごご)","p":"n","m":{"az":"günün ikinci yarısı","en":"p.m.; afternoon","ru":"после полудня"},"n":{"az":"Saatla gecə vaxtını da bildirə bilər: 午後九時 = axşam saat doqquz.","en":"With clock times, it also covers evening: 午後九時 = 9 p.m.","ru":"Со временем обозначает и вечер: 午後九時 = девять часов вечера."}},"参加":{"b":"参加 (さんか)","p":"n","m":{"az":"iştirak; qatılma","en":"participation; joining","ru":"участие; присоединение"},"n":{"az":"参加する iştirak etməkdir; tədbir adətən に ilə göstərilir: 会議に参加する.","en":"参加する means to participate; the event takes に: 会議に参加する.","ru":"参加する означает участвовать; мероприятие обозначается частицей に: 会議に参加する."}},"友だち":{"b":"友達 (ともだち)","p":"n","m":{"az":"dost","en":"friend","ru":"друг, подруга"}},"夏":{"b":"夏 (なつ)","p":"n","m":{"az":"yay","en":"summer","ru":"лето"}},"夏休み":{"b":"夏休み (なつやすみ)","p":"n","m":{"az":"yay tətili","en":"summer vacation; summer break","ru":"летние каникулы; летний отпуск"}},"夕方":{"b":"夕方 (ゆうがた)","p":"n","m":{"az":"axşamüstü","en":"evening","ru":"вечер"}},"外れる":{"b":"外れる (はずれる)","p":"v","m":{"az":"yerindən çıxmaq; ayrılmaq","en":"to come off; to become detached","ru":"отсоединяться; спадать"},"n":{"az":"Təsirsiz feldir; 外す nəyisə çıxarmaq deməkdir.","en":"Intransitive verb; 外す means to remove something.","ru":"Непереходный глагол; 外す означает снимать что-либо."}},"夜":{"b":"夜 (よる)","p":"n","m":{"az":"gecə","en":"night","ru":"ночь"}},"大きい":{"b":"大きい (おおきい)","p":"ai","m":{"az":"böyük","en":"big","ru":"большой"},"n":{"az":"大きくなる = böyümək (い → く + なる).","en":"大きくなる = grow up.","ru":"大きくなる = вырасти."}},"大きな":{"b":"大きな (おおきな)","p":"dm","m":{"az":"böyük","en":"big","ru":"большой"},"n":{"az":"Yalnız isimdən əvvəl gəlir; 大きい ilə eyni mənadadır.","en":"Only before a noun; same as 大きい.","ru":"Только перед сущ.; то же, что 大きい."}},"大切":{"b":"大切 (たいせつ)","p":"an","m":{"az":"vacib, əziz","en":"important, precious","ru":"важный, дорогой"},"n":{"az":"Na-sifətidir: 大切な物 “əziz əşya”; 大切にする “qayğı ilə yanaşmaq, əziz tutmaq” deməkdir.","en":"A na-adjective: 大切な物 “a precious thing”; 大切にする means “cherish or take good care of.”","ru":"Прилагательное на な: 大切な物 «дорогая вещь»; 大切にする означает «беречь, дорожить»."}},"女の子":{"b":"女の子 (おんなのこ)","p":"n","m":{"az":"qız uşağı","en":"girl","ru":"девочка"}},"好き":{"b":"好き (すき)","p":"an","m":{"az":"sevimli; sevmək","en":"liked; to like","ru":"любимый; нравиться"},"n":{"az":"N が好きです = N-i sevirəm. Yaponcada 'sevmək' sifətlə deyilir.","en":"N が好きです = I like N. 'To like' is an adjective in Japanese.","ru":"N が好きです = мне нравится N. 'Нравиться' – прилагательное."}},"始める":{"b":"始める (はじめる)","p":"v","m":{"az":"başlamaq, başlatmaq","en":"to begin, to start something","ru":"начинать"},"n":{"az":"Təsirli feldir, 勉強を始めます dərsə başlamaqdır, təsirsiz qarşılığı 始まる-dur.","en":"Transitive: 勉強を始めます means start studying, while 始まる is intransitive.","ru":"Переходный глагол: 勉強を始めます - начать учёбу, непереходный вариант 始まる."}},"子どもたち":{"b":"子どもたち (こどもたち)","p":"n","m":{"az":"uşaqlar","en":"children","ru":"дети"},"n":{"az":"たち insanları və bəzən canlıları bildirən sözlərə cəm və ya qrup mənası verir.","en":"たち marks a plural or group, mainly with words for people and sometimes other living beings.","ru":"たち обозначает множественность или группу, главным образом у слов, называющих людей, иногда других живых существ."}},"子ぶた":{"b":"子豚 (こぶた)","p":"n","m":{"az":"donuz balası","en":"piglet","ru":"поросёнок"}},"子ぶたたち":{"b":"子豚たち (こぶたたち)","p":"n","m":{"az":"donuz balaları","en":"piglets","ru":"поросята"},"n":{"az":"たち burada heyvan balalarının bir qrupunu bildirir.","en":"たち here refers to a group of piglets.","ru":"たち здесь обозначает группу поросят."}},"宇宙":{"b":"宇宙 (うちゅう)","p":"n","m":{"az":"kosmos; kainat","en":"outer space; universe","ru":"космос; вселенная"}},"完成":{"b":"完成 (かんせい)","p":"n","m":{"az":"tamamlanma; başa çatma","en":"completion; finishing","ru":"завершение; окончание"},"n":{"az":"完成する bir şeyin tam hazır olması deməkdir: 家が完成する.","en":"完成する means to be completed: 家が完成する.","ru":"完成する означает быть полностью завершённым: 家が完成する."}},"家":{"b":"家 (いえ)","p":"n","m":{"az":"ev","en":"house, home","ru":"дом"}},"家族":{"b":"家族 (かぞく)","p":"n","m":{"az":"ailə","en":"family","ru":"семья"}},"小さい":{"b":"小さい (ちいさい)","p":"ai","m":{"az":"balaca, kiçik","en":"small, little","ru":"маленький"},"n":{"az":"i-sifət; isimdən əvvəl olduğu kimi gəlir: 小さい子 = balaca uşaq.","en":"i-adjective; goes straight before a noun: 小さい子 = a little child.","ru":"i-прилагательное; ставится прямо перед существительным."}},"小さな":{"b":"小さな (ちいさな)","p":"dm","m":{"az":"balaca, kiçik","en":"small, little","ru":"маленький"},"n":{"az":"Yalnız isimdən əvvəl gəlir (小さな音). Mənaca 小さい ilə eynidir.","en":"Only used before a noun; same meaning as 小さい.","ru":"Только перед существительным; то же, что 小さい."}},"少し":{"b":"少し (すこし)","p":"ad","m":{"az":"bir az","en":"a little","ru":"немного"}},"帰る":{"b":"帰る (かえる)","p":"v","m":{"az":"qayıtmaq (evə, öz yerinə)","en":"to return home","ru":"возвращаться"},"n":{"az":"家へ帰るとちゅうで = evə qayıdarkən yolda.","en":"家へ帰るとちゅうで = on the way home.","ru":"家へ帰るとちゅうで = по дороге домой."}},"帽子":{"b":"帽子 (ぼうし)","p":"n","m":{"az":"papaq; şlyapa","en":"hat; cap","ru":"шляпа; шапка"}},"広場":{"b":"広場 (ひろば)","p":"n","m":{"az":"meydan, açıq sahə","en":"square, open space","ru":"площадь, открытое пространство"}},"床":{"b":"床 (ゆか)","p":"n","m":{"az":"döşəmə","en":"floor","ru":"пол"}},"庭":{"b":"庭 (にわ)","p":"n","m":{"az":"bağça, həyət","en":"garden, yard","ru":"сад, двор"}},"弟":{"b":"弟 (おとうと)","p":"n","m":{"az":"kiçik qardaş","en":"younger brother","ru":"младший брат"},"n":{"az":"Adətən öz kiçik qardaşından danışarkən işlənir.","en":"Usually used when speaking about one's own younger brother.","ru":"Обычно используется при упоминании своего младшего брата."}},"強い":{"b":"強い (つよい)","p":"ai","m":{"az":"güclü, qüvvətli","en":"strong, powerful","ru":"сильный"},"n":{"az":"い-sifətdir; əksi 弱い - zəif.","en":"An i-adjective; its opposite is 弱い, weak.","ru":"Это i-прилагательное; антоним 弱い - слабый."}},"心配":{"b":"心配 (しんぱい)","p":"n","m":{"az":"narahatlıq, qayğı","en":"worry, concern","ru":"беспокойство, тревога"},"n":{"az":"心配する “narahat olmaq” deməkdir; 心配な şəklində na-sifəti kimi də işlənir.","en":"心配する means “worry”; 心配な is also used as a na-adjective.","ru":"心配する означает «беспокоиться»; форма 心配な также употребляется как прилагательное на な."}},"思う":{"b":"思う (おもう)","p":"v","m":{"az":"düşünmək, fikirləşmək","en":"to think","ru":"думать"},"n":{"az":"〜と思いました = ...deyə düşündü.","en":"〜と思いました = thought that ...","ru":"〜と思いました = подумал, что ..."}},"急":{"b":"急 (きゅう)","p":"an","m":{"az":"qəfil, birdən","en":"sudden","ru":"внезапный"},"n":{"az":"急に = birdən, qəfildən.","en":"急に = suddenly.","ru":"急に = вдруг."}},"急ぐ":{"b":"急ぐ (いそぐ)","p":"v","m":{"az":"tələsmək","en":"hurry","ru":"спешить"},"n":{"az":"て forması 急いで olur.","en":"Its て-form is 急いで.","ru":"Форма на て: 急いで."}},"悲しい":{"b":"悲しい (かなしい)","p":"ai","m":{"az":"kədərli","en":"sad","ru":"грустный"},"n":{"az":"İ-sifətidir; 悲しく zərf formasıdır və “kədərli şəkildə” mənasını verir.","en":"An i-adjective; 悲しく is its adverbial form, meaning “sadly.”","ru":"Прилагательное на い; 悲しく является наречной формой со значением «грустно»."}},"手伝う":{"b":"手伝う (てつだう)","p":"v","m":{"az":"kömək etmək","en":"to help; to assist","ru":"помогать"},"n":{"az":"手伝いましょう təklif bildirir: kömək edim.","en":"手伝いましょう offers help: shall I help?","ru":"手伝いましょう выражает предложение помощи: давайте помогу."}},"押す":{"b":"押す (おす)","p":"v","m":{"az":"basmaq; itələmək","en":"to push; to press","ru":"толкать; нажимать"},"n":{"az":"ボタンを押す düyməni basmaq deməkdir.","en":"ボタンを押す means to press a button.","ru":"ボタンを押す означает нажать кнопку."}},"持つ":{"b":"持つ (もつ)","p":"v","m":{"az":"tutmaq, daşımaq; sahib olmaq","en":"to hold, to carry; to have","ru":"держать, нести; иметь"},"n":{"az":"かばんを持って = çantanı tutub (te-forması: hərəkətlər ardıcıllığı).","en":"かばんを持って = holding a bag.","ru":"かばんを持って = держа сумку."}},"振る":{"b":"振る (ふる)","p":"v","m":{"az":"yelləmək; silkələmək","en":"wave; shake","ru":"махать; трясти"},"n":{"az":"手を振る əl yelləmək, 首を振る isə başı yelləmək deməkdir.","en":"手を振る means to wave a hand; 首を振る means to shake one's head.","ru":"手を振る означает махать рукой, а 首を振る качать головой."}},"探す":{"b":"探す (さがす)","p":"v","m":{"az":"axtarmaq","en":"to search for, to look for","ru":"искать"},"n":{"az":"探しましょう birlikdə axtarmağı təklif edir.","en":"探しましょう means \"Let's look for it.\"","ru":"探しましょう означает «Давайте поищем»."}},"新しい":{"b":"新しい (あたらしい)","p":"ai","m":{"az":"yeni","en":"new","ru":"новый"}},"旅行":{"b":"旅行 (りょこう)","p":"n","m":{"az":"səyahət","en":"travel; trip","ru":"путешествие; поездка"},"n":{"az":"旅行する = səyahət etmək; 旅行に行く = səyahətə getmək.","en":"旅行する means to travel; 旅行に行く means to go on a trip.","ru":"旅行する означает путешествовать; 旅行に行く означает отправляться в поездку."}},"日":{"b":"日 (ひ)","p":"n","m":{"az":"gün; günəş","en":"day; sun","ru":"день; солнце"},"n":{"az":"Müstəqil söz kimi çox vaxt ひ oxunur; tarixlərdə və birləşmələrdə oxunuşu dəyişir.","en":"Usually read ひ as a standalone word; its reading changes in dates and compounds.","ru":"Как отдельное слово обычно читается ひ; в датах и сложных словах чтение меняется."}},"早い":{"b":"早い (はやい)","p":"ai","m":{"az":"erkən; tez","en":"early","ru":"ранний; рано"},"n":{"az":"い-sifətidir; 早く zərf formasıdır, sürət mənasında isə 速い yazılır.","en":"An い-adjective; 早く is its adverb form, while 速い refers to speed.","ru":"い-прилагательное; 早く является наречной формой, а 速い обозначает скорость."}},"明日":{"b":"明日 (あした)","p":"n","m":{"az":"sabah","en":"tomorrow","ru":"завтра"},"n":{"az":"Vaxt bildirəndə adətən に işlənmir: 明日行きます.","en":"Usually takes no に as a time expression: 明日行きます.","ru":"При обозначении времени обычно употребляется без に: 明日行きます."}},"星":{"b":"星 (ほし)","p":"n","m":{"az":"ulduz","en":"star","ru":"звезда"}},"星空":{"b":"星空 (ほしぞら)","p":"n","m":{"az":"ulduzlu səma","en":"starry sky","ru":"звёздное небо"}},"春":{"b":"春 (はる)","p":"n","m":{"az":"yaz (fəsil)","en":"spring","ru":"весна"}},"時間":{"b":"時間 (じかん)","p":"n","m":{"az":"vaxt, saat","en":"time, hour","ru":"время, час"},"n":{"az":"食べる時間 = yemək vaxtı (feil isimdən əvvəl).","en":"食べる時間 = the time to eat.","ru":"食べる時間 = время еды."}},"暮らす":{"b":"暮らす (くらす)","p":"v","m":{"az":"yaşamaq; həyat sürmək","en":"to live; to spend one's life","ru":"жить; проводить жизнь"},"n":{"az":"暮らす gündəlik həyat tərzini vurğulayır: 家族と暮らす.","en":"暮らす emphasizes everyday living: 家族と暮らす.","ru":"暮らす подчёркивает повседневную жизнь: 家族と暮らす."}},"朝":{"b":"朝 (あさ)","p":"n","m":{"az":"səhər","en":"morning","ru":"утро"}},"木":{"b":"木 (き)","p":"n","m":{"az":"ağac; taxta","en":"tree; wood","ru":"дерево; древесина"}},"本当":{"b":"本当 (ほんとう)","p":"n","m":{"az":"həqiqət, doğru","en":"truth, reality","ru":"правда, истина"},"n":{"az":"本当です doğru deməkdir, 本当に isə həqiqətən mənasını verir.","en":"本当です means it is true, while 本当に means really.","ru":"本当です означает это правда, а 本当に - действительно."}},"材料":{"b":"材料 (ざいりょう)","p":"n","m":{"az":"material; inqrediyent","en":"material; ingredient","ru":"материал; ингредиент"}},"来る":{"b":"来る (くる)","p":"v","m":{"az":"gəlmək","en":"to come","ru":"приходить"},"n":{"az":"Qeyri-müntəzəm feildir: 来ます (kimasu), 来た (kita), 来て (kite). 〜から来ました = ...-dan gəlmişəm. 迎えに来る = aparmağa gəlmək.","en":"Irregular verb: 来ます, 来た (kita), 来て (kite). 〜から来ました = I come from ...","ru":"Неправильный глагол: 来ます, 来た (kita), 来て (kite). 〜から来ました = я из ..."}},"来年":{"b":"来年 (らいねん)","p":"n","m":{"az":"gələn il","en":"next year","ru":"следующий год"}},"森":{"b":"森 (もり)","p":"nm","m":{"az":"Mori (soyad; mənası 'meşə')","en":"Mori (surname; means 'forest')","ru":"Мори (фамилия; значит 'лес')"}},"植える":{"b":"植える (うえる)","p":"v","m":{"az":"əkmək; basdırmaq","en":"to plant","ru":"сажать; высаживать"},"n":{"az":"Təsirli feldir; bitki を ilə göstərilir: 木を植える.","en":"Transitive verb; the plant takes を: 木を植える.","ru":"Переходный глагол; растение обозначается частицей を: 木を植える."}},"楽しい":{"b":"楽しい (たのしい)","p":"ai","m":{"az":"əyləncəli; xoş","en":"fun; enjoyable","ru":"весёлый; приятный"},"n":{"az":"İ-sifətdir; 楽しく onun zərf formasıdır.","en":"An i-adjective; 楽しく is its adverbial form.","ru":"И-прилагательное; 楽しく является его наречной формой."}},"次":{"b":"次 (つぎ)","p":"n","m":{"az":"növbəti; sonrakı","en":"next; following","ru":"следующий"},"n":{"az":"İsimdən əvvəl 次の, ardıcıllıq bildirmək üçün 次に işlənir.","en":"Use 次の before a noun and 次に to mean next in a sequence.","ru":"Перед существительным используется 次の, а для следующего шага 次に."}},"毎日":{"b":"毎日 (まいにち)","p":"n","m":{"az":"hər gün","en":"every day","ru":"каждый день"}},"毎晩":{"b":"毎晩 (まいばん)","p":"n","m":{"az":"hər axşam; hər gecə","en":"every evening; every night","ru":"каждый вечер; каждую ночь"},"n":{"az":"Vaxt bildirəndə に işlənmir: 毎晩読みます.","en":"Takes no に as a time expression: 毎晩読みます.","ru":"При обозначении времени употребляется без に: 毎晩読みます."}},"毎週":{"b":"毎週 (まいしゅう)","p":"ad","m":{"az":"hər həftə","en":"every week","ru":"каждую неделю"}},"水":{"b":"水 (みず)","p":"n","m":{"az":"su","en":"water","ru":"вода"},"n":{"az":"水 adətən soyuq və ya otaq temperaturunda suyu, お湯 isə isti suyu bildirir.","en":"水 usually means cold or room-temperature water; お湯 means hot water.","ru":"水 обычно обозначает холодную воду или воду комнатной температуры, а お湯 означает горячую воду."}},"水着":{"b":"水着 (みずぎ)","p":"n","m":{"az":"çimərlik geyimi; üzgüçülük geyimi","en":"swimsuit; swimwear","ru":"купальник; плавательный костюм"}},"決める":{"b":"決める (きめる)","p":"v","m":{"az":"qərar vermək, müəyyənləşdirmək","en":"to decide, to choose","ru":"решать, выбирать"},"n":{"az":"Nを決める nəyisə müəyyənləşdirmək, Nに決める isə N-i seçmək deməkdir; təsirsiz qarşılığı 決まる-dır.","en":"Nを決める means to decide something, Nに決める to choose N; the intransitive counterpart is 決まる.","ru":"Nを決める означает решить что-либо, Nに決める выбрать N; непереходная пара: 決まる."}},"泣く":{"b":"泣く (なく)","p":"v","m":{"az":"ağlamaq","en":"to cry","ru":"плакать"}},"海":{"b":"海 (うみ)","p":"n","m":{"az":"dəniz","en":"sea","ru":"море"}},"温かい":{"b":"温かい (あたたかい)","p":"ai","m":{"az":"isti; ilıq; mehriban","en":"warm; kind","ru":"тёплый; душевный"},"n":{"az":"い-sifətidir; əşya və münasibətlər üçün 温かい, hava üçün adətən 暖かい yazılır.","en":"An い-adjective; 温かい is used for objects and kindness, while weather usually takes 暖かい.","ru":"い-прилагательное; 温かい относится к предметам и душевной теплоте, а для погоды обычно пишут 暖かい."}},"犬":{"b":"犬 (いぬ)","p":"n","m":{"az":"it","en":"dog","ru":"собака"}},"町":{"b":"町 (まち)","p":"n","m":{"az":"şəhərcik; məhəllə","en":"town; neighborhood","ru":"городок; квартал"}},"百ぴき":{"b":"百匹 (ひゃっぴき)","p":"nu","m":{"az":"yüz heyvan; yüz ədəd kiçik heyvan","en":"one hundred small animals","ru":"сто небольших животных"},"n":{"az":"匹 sayğacında 百匹 ひゃっぴき, 三百匹 さんびゃっぴき kimi səs dəyişmələri olur.","en":"The 匹 counter has sound changes: 百匹 is ひゃっぴき and 三百匹 is さんびゃっぴき.","ru":"У счётного суффикса 匹 есть изменения звуков: 百匹 читается ひゃっぴき, 三百匹 さんびゃっぴき."}},"直す":{"b":"直す (なおす)","p":"v","m":{"az":"düzəltmək; təmir etmək","en":"to fix; to repair; to correct","ru":"чинить; исправлять"},"n":{"az":"Təsirli feldir, 直る isə düzəlməkdir; 書き直す yenidən yazmaq deməkdir.","en":"Transitive verb paired with 直る, to get fixed; 書き直す means to rewrite.","ru":"Переходный глагол, пара 直る означает исправляться; 書き直す означает переписывать."}},"相談":{"b":"相談 (そうだん)","p":"n","m":{"az":"məsləhətləşmə; məsləhət alma","en":"consultation; discussion","ru":"совет; консультация"},"n":{"az":"〜に相談する kimdənsə məsləhət almaq deməkdir: 先生に相談する.","en":"〜に相談する means to consult someone: 先生に相談する.","ru":"〜に相談する означает советоваться с кем-либо: 先生に相談する."}},"石":{"b":"石 (いし)","p":"n","m":{"az":"daş","en":"stone, rock","ru":"камень"}},"穴":{"b":"穴 (あな)","p":"n","m":{"az":"deşik; çuxur","en":"hole; pit","ru":"отверстие; яма"}},"空":{"b":"空 (そら)","p":"n","m":{"az":"göy, səma","en":"sky","ru":"небо"}},"窓":{"b":"窓 (まど)","p":"n","m":{"az":"pəncərə","en":"window","ru":"окно"}},"笑う":{"b":"笑う (わらう)","p":"v","m":{"az":"gülmək, gülümsəmək","en":"to laugh, to smile","ru":"смеяться, улыбаться"},"n":{"az":"笑うと = gülümsəyəndə (feil + と = 'edəndə').","en":"笑うと = when he smiled.","ru":"笑うと = когда он улыбался."}},"紙":{"b":"紙 (かみ)","p":"n","m":{"az":"kağız","en":"paper","ru":"бумага"}},"絵":{"b":"絵 (え)","p":"n","m":{"az":"şəkil, rəsm","en":"picture, drawing","ru":"картина, рисунок"}},"線":{"b":"線 (せん)","p":"n","m":{"az":"xətt; cizgi","en":"line; stroke","ru":"линия; черта"}},"考える":{"b":"考える (かんがえる)","p":"v","m":{"az":"düşünmək, fikirləşmək, nəzərdən keçirmək","en":"to think, to consider","ru":"думать, обдумывать, рассматривать"},"n":{"az":"〜について考える - bir mövzu haqqında düşünmək.","en":"〜について考える means to think about a topic.","ru":"〜について考える означает думать о какой-либо теме."}},"聞く":{"b":"聞く (きく)","p":"v","m":{"az":"soruşmaq; eşitmək, qulaq asmaq","en":"to ask; to hear, listen","ru":"спрашивать; слушать"},"n":{"az":"Burada 'soruşmaq': 「…」と聞くと = «…» deyə soruşanda.","en":"Here 'ask': 「…」と聞くと = when she asked \"…\".","ru":"Здесь 'спросить': 「…」と聞くと = когда спросила «…»."}},"自分":{"b":"自分 (じぶん)","p":"n","m":{"az":"öz, özü","en":"oneself","ru":"сам, свой"},"n":{"az":"自分の名前 = öz adı.","en":"自分の名前 = one's own name.","ru":"自分の名前 = своё имя."}},"船":{"b":"船 (ふね)","p":"n","m":{"az":"gəmi, qayıq","en":"ship, boat","ru":"корабль, лодка"}},"花":{"b":"花 (はな)","p":"n","m":{"az":"çiçək","en":"flower","ru":"цветок"}},"行く":{"b":"行く (いく)","p":"v","m":{"az":"getmək","en":"go","ru":"идти; ехать"},"n":{"az":"İstiqamət に və ya へ ilə göstərilir; て forması 行って, keçmiş forması 行った olur.","en":"The destination takes に or へ; its irregular forms are 行って and 行った.","ru":"Направление обозначается に или へ; особые формы: 行って и 行った."}},"見る":{"b":"見る (みる)","p":"v","m":{"az":"baxmaq, görmək","en":"to see, to look","ru":"смотреть, видеть"},"n":{"az":"月を見てください = Aya baxın.","en":"月を見てください = please look at the moon.","ru":"月を見てください = смотрите на луну."}},"言う":{"b":"言う (いう)","p":"v","m":{"az":"demək","en":"to say","ru":"сказать, говорить"},"n":{"az":"「…」と言いました = «…» dedi. Oxunuşu 'iu' kimi səslənir.","en":"「…」と言いました = said \"…\". Pronounced 'yuu'.","ru":"「…」と言いました = сказал «…»."}},"計画":{"b":"計画 (けいかく)","p":"n","m":{"az":"plan; layihə","en":"plan; project","ru":"план; проект"},"n":{"az":"計画する planlaşdırmaq deməkdir; 計画を立てる plan qurmaq ifadəsidir.","en":"計画する means to plan; 計画を立てる means to make a plan.","ru":"計画する означает планировать; 計画を立てる означает составлять план."}},"調べる":{"b":"調べる (しらべる)","p":"v","m":{"az":"araşdırmaq, yoxlamaq","en":"to investigate, to check, to look up","ru":"исследовать, проверять, искать сведения"},"n":{"az":"Söz və məlumat axtarışında da işlənir: 辞書で調べます.","en":"Also used to look up information: 辞書で調べます means to check in a dictionary.","ru":"Также используется для поиска сведений: 辞書で調べます - посмотреть в словаре."}},"買う":{"b":"買う (かう)","p":"v","m":{"az":"almaq; satın almaq","en":"buy","ru":"покупать"},"n":{"az":"て forması 買って olur.","en":"Its て-form is 買って.","ru":"Форма на て: 買って."}},"走る":{"b":"走る (はしる)","p":"v","m":{"az":"qaçmaq","en":"run","ru":"бежать"},"n":{"az":"る ilə bitsə də birinci qrup feldir; 走らせる qaçırmaq, 車を走らせる isə maşını sürmək deməkdir.","en":"Despite ending in る, it is a group 1 verb; 走らせる means make run, and 車を走らせる means drive a car.","ru":"Несмотря на る, это глагол первой группы; 走らせる означает заставить бежать, а 車を走らせる вести машину."}},"足りる":{"b":"足りる (たりる)","p":"v","m":{"az":"kifayət etmək; çatmaq","en":"to be enough; to suffice","ru":"хватать; быть достаточным"},"n":{"az":"足りませんでした keçmiş zamanda kifayət etmədi deməkdir.","en":"足りませんでした means was not enough in the past.","ru":"足りませんでした означает не хватило в прошлом."}},"軽い":{"b":"軽い (かるい)","p":"ai","m":{"az":"yüngül","en":"light, lightweight","ru":"лёгкий"},"n":{"az":"い-sifətdir; əksi 重い - ağır.","en":"An i-adjective; its opposite is 重い, heavy.","ru":"Это i-прилагательное; антоним 重い - тяжёлый."}},"近く":{"b":"近く (ちかく)","p":"n","m":{"az":"yaxınlıq, yaxın yer","en":"vicinity, nearby place","ru":"окрестности, близкое место"},"n":{"az":"Nの近く “N-in yaxınlığı”, 近くに isə “yaxınlıqda” deməkdir.","en":"Nの近く means “near N,” and 近くに means “nearby.”","ru":"Nの近く означает «рядом с N», а 近くに означает «поблизости»."}},"追いかける":{"b":"追いかける (おいかける)","p":"v","m":{"az":"arxasınca qaçmaq; təqib etmək","en":"to chase; to run after","ru":"гнаться; преследовать"},"n":{"az":"追いかける adətən hərəkət edən birinin və ya nəyinsə arxasınca getməyi bildirir.","en":"追いかける usually means to chase someone or something moving away.","ru":"追いかける обычно означает преследовать кого-либо или что-либо удаляющееся."}},"連れる":{"b":"連れる (つれる)","p":"v","m":{"az":"özü ilə aparmaq, müşayiət etmək","en":"to take along, to accompany","ru":"брать с собой, вести"},"n":{"az":"連れて行く birini aparmaq, 連れて来る isə birini gətirmək deməkdir.","en":"連れて行く means to take someone along; 連れて来る means to bring someone.","ru":"連れて行く означает взять кого-то с собой, а 連れて来る означает привести кого-то."}},"遊ぶ":{"b":"遊ぶ (あそぶ)","p":"v","m":{"az":"oynamaq; əylənmək","en":"to play; to have fun","ru":"играть; развлекаться"},"n":{"az":"て-forması 遊んで-dir; 友達と遊ぶ = dostlarla oynamaq və ya vaxt keçirmək.","en":"Its て-form is 遊んで; 友達と遊ぶ means to play or spend time with friends.","ru":"て-форма: 遊んで; 友達と遊ぶ означает играть или проводить время с друзьями."}},"運ぶ":{"b":"運ぶ (はこぶ)","p":"v","m":{"az":"daşımaq","en":"to carry, to transport","ru":"нести, перевозить"},"n":{"az":"て forması 運んで-dir; 荷物を運ぶ yük daşımaq deməkdir.","en":"The て-form is 運んで; 荷物を運ぶ means to carry luggage.","ru":"Форма на て: 運んで; 荷物を運ぶ означает нести багаж."}},"遠く":{"b":"遠く (とおく)","p":"n","m":{"az":"uzaq yer, uzaqlıq","en":"faraway place, distance","ru":"далёкое место, даль"},"n":{"az":"遠い sifətinin formasıdır; 遠くに uzaqda deməkdir.","en":"Derived from 遠い; 遠くに means far away.","ru":"Образовано от 遠い; 遠くに означает далеко."}},"部屋":{"b":"部屋 (へや)","p":"n","m":{"az":"otaq","en":"room","ru":"комната"}},"開く":{"b":"開く (あく)","p":"v","m":{"az":"açılmaq","en":"open","ru":"открываться"},"n":{"az":"Qapı üçün あく oxunur və təsirsizdir, təsirli qarşılığı 開ける olur; 開く həmçinin ひらく oxuna bilər.","en":"For doors, it is read あく and is intransitive, paired with 開ける; 開く can also be read ひらく.","ru":"О дверях читается あく и является непереходным, с парой 開ける; 開く также может читаться ひらく."}},"開ける":{"b":"開ける (あける)","p":"v","m":{"az":"açmaq","en":"to open","ru":"открывать"},"n":{"az":"開けると = açanda.","en":"開けると = when he opened.","ru":"開けると = когда открыл."}},"集まる":{"b":"集まる (あつまる)","p":"v","m":{"az":"toplaşmaq; yığışmaq","en":"to gather; to assemble","ru":"собираться; сходиться"},"n":{"az":"自動詞-dir; 集める isə nəyisə toplamaqdır.","en":"An intransitive verb; 集める means to collect something.","ru":"Непереходный глагол; 集める означает собирать что-либо."}},"青い":{"b":"青い (あおい)","p":"ai","m":{"az":"mavi, göy","en":"blue","ru":"синий, голубой"}},"音楽":{"b":"音楽 (おんがく)","p":"n","m":{"az":"musiqi","en":"music","ru":"музыка"}},"風":{"b":"風 (かぜ)","p":"n","m":{"az":"külək","en":"wind","ru":"ветер"}},"飛ばす":{"b":"飛ばす (とばす)","p":"v","m":{"az":"uçurtmaq; havaya buraxmaq","en":"to make fly; to launch","ru":"запускать; заставлять летать"},"n":{"az":"他動詞: 飛ぶ uçmaq, 飛ばす isə uçurtmaq deməkdir.","en":"Transitive verb: 飛ぶ means to fly, while 飛ばす means to make something fly.","ru":"Переходный глагол: 飛ぶ означает лететь, а 飛ばす - запускать."}},"飛ぶ":{"b":"飛ぶ (とぶ)","p":"v","m":{"az":"uçmaq, havada hərəkət etmək","en":"to fly","ru":"летать, лететь"},"n":{"az":"Təsirsiz feldir, 飛びました nəzakətli keçmiş formadır.","en":"An intransitive verb, with 飛びました as its polite past form.","ru":"Непереходный глагол, 飛びました - его вежливая прошедшая форма."}},"食べる":{"b":"食べる (たべる)","p":"v","m":{"az":"yemək","en":"to eat","ru":"есть"}},"食べ物":{"b":"食べ物 (たべもの)","p":"n","m":{"az":"yemək; qida","en":"food; something to eat","ru":"еда; пища"}},"飼い主":{"b":"飼い主 (かいぬし)","p":"n","m":{"az":"heyvan sahibi","en":"pet owner; animal owner","ru":"хозяин животного; владелец питомца"}},"首輪":{"b":"首輪 (くびわ)","p":"n","m":{"az":"boyunluq, heyvan yaxalığı","en":"collar, animal collar","ru":"ошейник"}},"高い":{"b":"高い (たかい)","p":"ai","m":{"az":"hündür; baha","en":"high; expensive","ru":"высокий; дорогой"},"n":{"az":"い-sifətdir; 高かった keçmiş formadır.","en":"It is an i-adjective; 高かった is its past form.","ru":"Это i-прилагательное; 高かった - форма прошедшего времени."}},"魚":{"b":"魚 (さかな)","p":"n","m":{"az":"balıq","en":"fish","ru":"рыба"}}}};